export type CartLine = { sku: string; quantity: number };

export type Shortage = { sku: string; requested: number; available: number };

export type ReserveResult =
  | { ok: true; reservationId: string; expiresAt: number }
  | { ok: false; shortages: Shortage[] };

export type InventoryOptions = {
  /** How long a reservation holds stock before it lapses. Defaults to 10 minutes. */
  holdMs?: number;
  /** Clock in milliseconds. Injectable for tests. */
  now?: () => number;
};

type Reservation = { lines: Map<string, number>; expiresAt: number };

const DEFAULT_HOLD_MS = 10 * 60 * 1000;

/**
 * In-memory stock per SKU with time-limited reservations for cart items.
 *
 * `available(sku)` is stock minus units held by live reservations. A reservation
 * is all-or-nothing: either every line can be held, or the customer gets the list
 * of shortages. Reservations that are not committed before they expire release
 * their stock automatically.
 */
export class Inventory {
  #stock = new Map<string, number>();
  #held = new Map<string, number>();
  #reservations = new Map<string, Reservation>();
  #holdMs: number;
  #now: () => number;
  #nextId = 1;

  constructor(stock: Record<string, number>, options: InventoryOptions = {}) {
    for (const [sku, units] of Object.entries(stock)) {
      assertNonNegativeInteger(units, `stock for ${sku}`);
      this.#stock.set(sku, units);
    }
    this.#holdMs = options.holdMs ?? DEFAULT_HOLD_MS;
    this.#now = options.now ?? Date.now;
  }

  available(sku: string): number {
    this.#expireLapsed();
    return this.#availableNow(sku);
  }

  /** Hold stock for every line of a cart, or report what cannot be fulfilled. */
  reserve(lines: CartLine[]): ReserveResult {
    this.#expireLapsed();

    const wanted = new Map<string, number>();
    for (const line of lines) {
      assertPositiveInteger(line.quantity, `quantity for ${line.sku}`);
      wanted.set(line.sku, (wanted.get(line.sku) ?? 0) + line.quantity);
    }

    const shortages: Shortage[] = [];
    for (const [sku, requested] of wanted) {
      const available = this.#availableNow(sku);
      if (requested > available) shortages.push({ sku, requested, available });
    }
    if (shortages.length > 0) return { ok: false, shortages };

    const reservationId = `r${this.#nextId++}`;
    const expiresAt = this.#now() + this.#holdMs;
    for (const [sku, units] of wanted) {
      this.#held.set(sku, (this.#held.get(sku) ?? 0) + units);
    }
    this.#reservations.set(reservationId, { lines: wanted, expiresAt });
    return { ok: true, reservationId, expiresAt };
  }

  /** Give back a reservation's stock, e.g. when the customer leaves checkout. */
  release(reservationId: string): void {
    this.#expireLapsed();
    const reservation = this.#reservations.get(reservationId);
    if (!reservation) return;
    this.#unhold(reservation);
    this.#reservations.delete(reservationId);
  }

  /** Turn a live reservation into a sale: stock is decremented and the hold cleared. */
  commit(reservationId: string): void {
    this.#expireLapsed();
    const reservation = this.#reservations.get(reservationId);
    if (!reservation) {
      throw new Error(`reservation ${reservationId} is unknown or has expired`);
    }
    for (const [sku, units] of reservation.lines) {
      this.#stock.set(sku, (this.#stock.get(sku) ?? 0) - units);
    }
    this.#unhold(reservation);
    this.#reservations.delete(reservationId);
  }

  #availableNow(sku: string): number {
    return (this.#stock.get(sku) ?? 0) - (this.#held.get(sku) ?? 0);
  }

  #unhold(reservation: Reservation): void {
    for (const [sku, units] of reservation.lines) {
      this.#held.set(sku, (this.#held.get(sku) ?? 0) - units);
    }
  }

  #expireLapsed(): void {
    const now = this.#now();
    for (const [id, reservation] of this.#reservations) {
      if (reservation.expiresAt <= now) {
        this.#unhold(reservation);
        this.#reservations.delete(id);
      }
    }
  }
}

function assertPositiveInteger(value: number, label: string): void {
  if (!Number.isInteger(value) || value <= 0) {
    throw new RangeError(`${label} must be a positive integer, got ${value}`);
  }
}

function assertNonNegativeInteger(value: number, label: string): void {
  if (!Number.isInteger(value) || value < 0) {
    throw new RangeError(`${label} must be a non-negative integer, got ${value}`);
  }
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { Inventory } from "../src/inventory.ts";

function clock(start = 0) {
  let t = start;
  return {
    now: () => t,
    advance: (ms: number) => {
      t += ms;
    },
  };
}

test("available reflects stock when nothing is reserved", () => {
  const inv = new Inventory({ "tee-m": 5 });
  assert.equal(inv.available("tee-m"), 5);
  assert.equal(inv.available("unknown"), 0);
});

test("reserve holds stock so other customers see less available", () => {
  const inv = new Inventory({ "tee-m": 5 });
  const result = inv.reserve([{ sku: "tee-m", quantity: 3 }]);
  assert.equal(result.ok, true);
  assert.equal(inv.available("tee-m"), 2);
});

test("reserve is all-or-nothing and reports every shortage", () => {
  const inv = new Inventory({ "tee-m": 1, "cap": 4 });
  const result = inv.reserve([
    { sku: "tee-m", quantity: 2 },
    { sku: "cap", quantity: 1 },
    { sku: "mug", quantity: 1 },
  ]);
  assert.deepEqual(result, {
    ok: false,
    shortages: [
      { sku: "tee-m", requested: 2, available: 1 },
      { sku: "mug", requested: 1, available: 0 },
    ],
  });
  assert.equal(inv.available("tee-m"), 1);
  assert.equal(inv.available("cap"), 4);
});

test("a second customer is told when the first reservation took the last units", () => {
  const inv = new Inventory({ "tee-m": 2 });
  assert.equal(inv.reserve([{ sku: "tee-m", quantity: 2 }]).ok, true);
  const second = inv.reserve([{ sku: "tee-m", quantity: 1 }]);
  assert.deepEqual(second, {
    ok: false,
    shortages: [{ sku: "tee-m", requested: 1, available: 0 }],
  });
});

test("duplicate lines for the same SKU are added together", () => {
  const inv = new Inventory({ "tee-m": 3 });
  const result = inv.reserve([
    { sku: "tee-m", quantity: 2 },
    { sku: "tee-m", quantity: 2 },
  ]);
  assert.equal(result.ok, false);
  if (!result.ok) {
    assert.deepEqual(result.shortages, [{ sku: "tee-m", requested: 4, available: 3 }]);
  }
});

test("commit turns the hold into a sale", () => {
  const inv = new Inventory({ "tee-m": 5 });
  const result = inv.reserve([{ sku: "tee-m", quantity: 3 }]);
  assert.equal(result.ok, true);
  if (!result.ok) return;
  inv.commit(result.reservationId);
  assert.equal(inv.available("tee-m"), 2);
  assert.throws(() => inv.commit(result.reservationId), /unknown or has expired/);
});

test("release gives the stock back and is idempotent", () => {
  const inv = new Inventory({ "tee-m": 5 });
  const result = inv.reserve([{ sku: "tee-m", quantity: 3 }]);
  assert.equal(result.ok, true);
  if (!result.ok) return;
  inv.release(result.reservationId);
  inv.release(result.reservationId);
  assert.equal(inv.available("tee-m"), 5);
});

test("a reservation lapses after the hold time and frees its stock", () => {
  const time = clock(1_000);
  const inv = new Inventory({ "tee-m": 2 }, { holdMs: 60_000, now: time.now });
  const result = inv.reserve([{ sku: "tee-m", quantity: 2 }]);
  assert.equal(result.ok, true);
  if (!result.ok) return;
  assert.equal(result.expiresAt, 61_000);

  time.advance(59_999);
  assert.equal(inv.available("tee-m"), 0);

  time.advance(1);
  assert.equal(inv.available("tee-m"), 2);
  assert.throws(() => inv.commit(result.reservationId), /unknown or has expired/);
});

test("an expired reservation cannot be committed and does not reduce stock", () => {
  const time = clock();
  const inv = new Inventory({ "tee-m": 2 }, { holdMs: 1_000, now: time.now });
  const result = inv.reserve([{ sku: "tee-m", quantity: 1 }]);
  assert.equal(result.ok, true);
  if (!result.ok) return;
  time.advance(1_000);
  assert.throws(() => inv.commit(result.reservationId));
  assert.equal(inv.available("tee-m"), 2);
});

test("rejects non-positive or fractional quantities", () => {
  const inv = new Inventory({ "tee-m": 5 });
  assert.throws(() => inv.reserve([{ sku: "tee-m", quantity: 0 }]), RangeError);
  assert.throws(() => inv.reserve([{ sku: "tee-m", quantity: 1.5 }]), RangeError);
  assert.equal(inv.available("tee-m"), 5);
});

test("rejects invalid starting stock", () => {
  assert.throws(() => new Inventory({ "tee-m": -1 }), RangeError);
});

export type CartLine = { sku: string; quantity: number };

export type Shortage = { sku: string; requested: number; available: number };

export type ReserveResult =
  | { ok: true; reservationId: string; expiresAt: number }
  | { ok: false; shortages: Shortage[] };

export type ConfirmResult = { ok: true } | { ok: false; reason: "no-active-hold" };

export type InventoryOptions = {
  /** How long a reservation holds stock before it lapses. Default: 10 minutes. */
  holdTtlMs?: number;
  /** Clock in milliseconds. Injectable for tests. */
  now?: () => number;
};

type Hold = { lines: CartLine[]; expiresAt: number };

const DEFAULT_HOLD_TTL_MS = 10 * 60 * 1000;

/**
 * In-memory stock per SKU. A reservation holds units for a cart while the
 * customer checks out; confirming it removes the units for good, releasing it
 * (or letting it expire) returns them to sale.
 */
export class Inventory {
  readonly #onHand: Map<string, number>;
  readonly #reserved = new Map<string, number>();
  readonly #holds = new Map<string, Hold>();
  readonly #holdTtlMs: number;
  readonly #now: () => number;
  #nextId = 1;

  constructor(stock: Record<string, number>, options: InventoryOptions = {}) {
    this.#onHand = new Map(Object.entries(stock));
    for (const [sku, units] of this.#onHand) {
      if (!Number.isInteger(units) || units < 0) {
        throw new RangeError(`Invalid stock for ${sku}: ${units}`);
      }
    }
    this.#holdTtlMs = options.holdTtlMs ?? DEFAULT_HOLD_TTL_MS;
    this.#now = options.now ?? Date.now;
  }

  /** Units of `sku` that are neither sold nor held by an active reservation. */
  available(sku: string): number {
    this.#expireHolds();
    return this.#free(sku);
  }

  /**
   * Reserves every line of the cart, or none of them. If any line cannot be
   * covered, nothing is held and the shortages are returned so they can be
   * shown to the customer.
   */
  reserve(cart: CartLine[]): ReserveResult {
    this.#expireHolds();

    const wanted = new Map<string, number>();
    for (const { sku, quantity } of cart) {
      if (!Number.isInteger(quantity) || quantity <= 0) {
        throw new RangeError(`Invalid quantity for ${sku}: ${quantity}`);
      }
      wanted.set(sku, (wanted.get(sku) ?? 0) + quantity);
    }

    const shortages: Shortage[] = [];
    for (const [sku, requested] of wanted) {
      const available = this.#free(sku);
      if (requested > available) shortages.push({ sku, requested, available });
    }
    if (shortages.length > 0) return { ok: false, shortages };

    const lines = [...wanted].map(([sku, quantity]) => ({ sku, quantity }));
    for (const { sku, quantity } of lines) {
      this.#reserved.set(sku, (this.#reserved.get(sku) ?? 0) + quantity);
    }
    const reservationId = `R${this.#nextId++}`;
    const expiresAt = this.#now() + this.#holdTtlMs;
    this.#holds.set(reservationId, { lines, expiresAt });
    return { ok: true, reservationId, expiresAt };
  }

  /** Gives a reservation's units back to sale. Returns false if no such active hold exists. */
  release(reservationId: string): boolean {
    this.#expireHolds();
    const hold = this.#holds.get(reservationId);
    if (!hold) return false;
    this.#drop(reservationId, hold);
    return true;
  }

  /** Completes the sale: the held units are removed from stock. */
  confirm(reservationId: string): ConfirmResult {
    this.#expireHolds();
    const hold = this.#holds.get(reservationId);
    if (!hold) return { ok: false, reason: "no-active-hold" };
    for (const { sku, quantity } of hold.lines) {
      this.#onHand.set(sku, (this.#onHand.get(sku) ?? 0) - quantity);
    }
    this.#drop(reservationId, hold);
    return { ok: true };
  }

  #free(sku: string): number {
    return (this.#onHand.get(sku) ?? 0) - (this.#reserved.get(sku) ?? 0);
  }

  #drop(reservationId: string, hold: Hold): void {
    for (const { sku, quantity } of hold.lines) {
      const left = (this.#reserved.get(sku) ?? 0) - quantity;
      if (left > 0) this.#reserved.set(sku, left);
      else this.#reserved.delete(sku);
    }
    this.#holds.delete(reservationId);
  }

  #expireHolds(): void {
    const now = this.#now();
    for (const [id, hold] of this.#holds) {
      if (now >= hold.expiresAt) this.#drop(id, hold);
    }
  }
}

import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { Inventory } from "../src/inventory.ts";

function clock(start = 0) {
  let t = start;
  return {
    now: () => t,
    advance: (ms: number) => {
      t += ms;
    },
  };
}

describe("reserve", () => {
  it("holds stock for the cart and reduces what is available", () => {
    const inv = new Inventory({ "tee-m": 5 });
    const result = inv.reserve([{ sku: "tee-m", quantity: 2 }]);
    assert.equal(result.ok, true);
    assert.equal(inv.available("tee-m"), 3);
  });

  it("can reserve exactly the remaining stock", () => {
    const inv = new Inventory({ "tee-m": 5 });
    assert.equal(inv.reserve([{ sku: "tee-m", quantity: 5 }]).ok, true);
    assert.equal(inv.available("tee-m"), 0);
  });

  it("does not let a second customer take units that are held", () => {
    const inv = new Inventory({ "tee-m": 3 });
    assert.equal(inv.reserve([{ sku: "tee-m", quantity: 2 }]).ok, true);
    const second = inv.reserve([{ sku: "tee-m", quantity: 2 }]);
    assert.deepEqual(second, {
      ok: false,
      shortages: [{ sku: "tee-m", requested: 2, available: 1 }],
    });
  });

  it("reserves nothing when any line cannot be fulfilled, and reports every shortage", () => {
    const inv = new Inventory({ "tee-m": 5, "mug": 1 });
    const result = inv.reserve([
      { sku: "tee-m", quantity: 2 },
      { sku: "mug", quantity: 2 },
      { sku: "cap", quantity: 1 },
    ]);
    assert.deepEqual(result, {
      ok: false,
      shortages: [
        { sku: "mug", requested: 2, available: 1 },
        { sku: "cap", requested: 1, available: 0 },
      ],
    });
    assert.equal(inv.available("tee-m"), 5, "partial reservation must not be kept");
    assert.equal(inv.available("mug"), 1);
  });

  it("adds up repeated lines for the same SKU before checking stock", () => {
    const inv = new Inventory({ "tee-m": 5 });
    const result = inv.reserve([
      { sku: "tee-m", quantity: 3 },
      { sku: "tee-m", quantity: 3 },
    ]);
    assert.deepEqual(result, {
      ok: false,
      shortages: [{ sku: "tee-m", requested: 6, available: 5 }],
    });
  });

  it("rejects non-positive or fractional quantities", () => {
    const inv = new Inventory({ "tee-m": 5 });
    for (const quantity of [0, -1, 1.5]) {
      assert.throws(() => inv.reserve([{ sku: "tee-m", quantity }]), RangeError);
    }
  });

  it("rejects negative starting stock", () => {
    assert.throws(() => new Inventory({ "tee-m": -1 }), RangeError);
  });
});

describe("release", () => {
  it("returns held units to sale", () => {
    const inv = new Inventory({ "tee-m": 2 });
    const { reservationId } = inv.reserve([{ sku: "tee-m", quantity: 2 }]) as {
      reservationId: string;
    };
    assert.equal(inv.release(reservationId), true);
    assert.equal(inv.available("tee-m"), 2);
  });

  it("returns false for unknown or already released reservations", () => {
    const inv = new Inventory({ "tee-m": 2 });
    const { reservationId } = inv.reserve([{ sku: "tee-m", quantity: 1 }]) as {
      reservationId: string;
    };
    assert.equal(inv.release("nope"), false);
    assert.equal(inv.release(reservationId), true);
    assert.equal(inv.release(reservationId), false);
    assert.equal(inv.available("tee-m"), 2);
  });
});

describe("confirm", () => {
  it("removes the held units from stock permanently", () => {
    const inv = new Inventory({ "tee-m": 5 });
    const { reservationId } = inv.reserve([{ sku: "tee-m", quantity: 2 }]) as {
      reservationId: string;
    };
    assert.deepEqual(inv.confirm(reservationId), { ok: true });
    assert.equal(inv.available("tee-m"), 3);
    assert.equal(inv.release(reservationId), false);
    assert.equal(inv.confirm(reservationId).ok, false);
  });
});

describe("hold expiry", () => {
  it("frees the stock once the hold has lapsed", () => {
    const c = clock();
    const inv = new Inventory({ "tee-m": 1 }, { holdTtlMs: 1000, now: c.now });
    assert.equal(inv.reserve([{ sku: "tee-m", quantity: 1 }]).ok, true);

    c.advance(999);
    assert.equal(inv.available("tee-m"), 0, "still held just before expiry");

    c.advance(1);
    assert.equal(inv.available("tee-m"), 1, "released at expiry");
  });

  it("cannot be confirmed after it has lapsed, and the customer is told", () => {
    const c = clock();
    const inv = new Inventory({ "tee-m": 1 }, { holdTtlMs: 1000, now: c.now });
    const { reservationId } = inv.reserve([{ sku: "tee-m", quantity: 1 }]) as {
      reservationId: string;
    };
    c.advance(1000);
    assert.deepEqual(inv.confirm(reservationId), { ok: false, reason: "no-active-hold" });
    assert.equal(inv.available("tee-m"), 1);
  });

  it("reports the expiry time of a new hold", () => {
    const c = clock(500);
    const inv = new Inventory({ "tee-m": 1 }, { holdTtlMs: 1000, now: c.now });
    const result = inv.reserve([{ sku: "tee-m", quantity: 1 }]);
    assert.equal(result.ok && result.expiresAt, 1500);
  });
});

/** A failure that is expected to go away on retry (e.g. a database timeout). */
export class TransientError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'TransientError';
  }
}

/** The event refers to a customer account that does not exist. */
export class UnknownCustomerError extends Error {
  constructor(customerId: string) {
    super(`unknown customer: ${customerId}`);
    this.name = 'UnknownCustomerError';
  }
}

export type CreditOutcome = 'applied' | 'duplicate';

export interface LedgerOptions {
  /**
   * Called inside creditOnce after validation but before anything is committed.
   * Lets tests (or a real storage layer) simulate a temporary write failure.
   */
  beforeCommit?: () => void;
}

/**
 * In-memory ledger of customer balances (integer cents) and of the payment
 * event IDs that have already been applied.
 */
export class Ledger {
  readonly #balances = new Map<string, number>();
  readonly #appliedEvents = new Set<string>();
  readonly #beforeCommit: (() => void) | undefined;

  constructor(options: LedgerOptions = {}) {
    this.#beforeCommit = options.beforeCommit;
  }

  openAccount(customerId: string, balanceCents = 0): void {
    if (this.#balances.has(customerId)) {
      throw new Error(`account already exists: ${customerId}`);
    }
    this.#balances.set(customerId, balanceCents);
  }

  balance(customerId: string): number {
    const balance = this.#balances.get(customerId);
    if (balance === undefined) {
      throw new UnknownCustomerError(customerId);
    }
    return balance;
  }

  hasApplied(eventId: string): boolean {
    return this.#appliedEvents.has(eventId);
  }

  /**
   * Credits the customer and records the event ID as one unit: either both
   * happen or neither does. Re-applying an event that was already applied is a
   * no-op that returns 'duplicate', so provider redeliveries never double-credit.
   * Because the check and the update run synchronously, concurrent deliveries
   * of the same event cannot both apply.
   */
  creditOnce(eventId: string, customerId: string, amountCents: number): CreditOutcome {
    if (this.#appliedEvents.has(eventId)) {
      return 'duplicate';
    }
    const current = this.balance(customerId);
    if (!Number.isSafeInteger(amountCents) || amountCents <= 0) {
      throw new RangeError(`amountCents must be a positive integer, got ${amountCents}`);
    }

    this.#beforeCommit?.();

    this.#balances.set(customerId, current + amountCents);
    this.#appliedEvents.add(eventId);
    return 'applied';
  }
}

import { Ledger, TransientError, UnknownCustomerError } from './ledger.ts';

export const PAYMENT_SUCCEEDED = 'payment.succeeded';

export interface WebhookResult {
  /** HTTP status to return to the payment provider. */
  status: number;
  outcome: 'credited' | 'duplicate' | 'ignored' | 'invalid' | 'unknown_customer' | 'retry';
}

interface PaymentSucceededEvent {
  id: string;
  type: typeof PAYMENT_SUCCEEDED;
  data: { customerId: string; amountCents: number };
}

type ParseResult =
  | { ok: true; event: PaymentSucceededEvent | { id: string; type: string } }
  | { ok: false };

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function parseEvent(rawBody: string): ParseResult {
  let body: unknown;
  try {
    body = JSON.parse(rawBody);
  } catch {
    return { ok: false };
  }
  if (!isRecord(body) || typeof body.id !== 'string' || body.id === '' || typeof body.type !== 'string') {
    return { ok: false };
  }
  if (body.type !== PAYMENT_SUCCEEDED) {
    return { ok: true, event: { id: body.id, type: body.type } };
  }
  const data = body.data;
  if (
    !isRecord(data) ||
    typeof data.customerId !== 'string' ||
    data.customerId === '' ||
    typeof data.amountCents !== 'number' ||
    !Number.isSafeInteger(data.amountCents) ||
    data.amountCents <= 0
  ) {
    return { ok: false };
  }
  return {
    ok: true,
    event: {
      id: body.id,
      type: PAYMENT_SUCCEEDED,
      data: { customerId: data.customerId, amountCents: data.amountCents },
    },
  };
}

/**
 * Handles one webhook delivery. Status codes tell the provider what to do:
 * 200 means done (credited, duplicate, or ignored), 422 and 400 are permanent
 * failures that must not be retried, and 500 asks the provider to redeliver.
 */
export async function handlePaymentWebhook(rawBody: string, ledger: Ledger): Promise<WebhookResult> {
  const parsed = parseEvent(rawBody);
  if (!parsed.ok) {
    return { status: 400, outcome: 'invalid' };
  }
  const { event } = parsed;
  if (event.type !== PAYMENT_SUCCEEDED) {
    return { status: 200, outcome: 'ignored' };
  }
  const payment = event as PaymentSucceededEvent;

  try {
    const outcome = ledger.creditOnce(payment.id, payment.data.customerId, payment.data.amountCents);
    return outcome === 'applied'
      ? { status: 200, outcome: 'credited' }
      : { status: 200, outcome: 'duplicate' };
  } catch (error) {
    if (error instanceof TransientError) {
      return { status: 500, outcome: 'retry' };
    }
    if (error instanceof UnknownCustomerError) {
      return { status: 422, outcome: 'unknown_customer' };
    }
    throw error;
  }
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { Ledger, TransientError } from '../src/ledger.ts';
import { handlePaymentWebhook } from '../src/webhook.ts';

function paymentEvent(id: string, customerId = 'cust_1', amountCents = 500): string {
  return JSON.stringify({ id, type: 'payment.succeeded', data: { customerId, amountCents } });
}

function newLedger(options?: ConstructorParameters<typeof Ledger>[0]): Ledger {
  const ledger = new Ledger(options);
  ledger.openAccount('cust_1', 1000);
  return ledger;
}

test('a payment event credits the customer balance', async () => {
  const ledger = newLedger();
  const result = await handlePaymentWebhook(paymentEvent('evt_1', 'cust_1', 500), ledger);
  assert.deepEqual(result, { status: 200, outcome: 'credited' });
  assert.equal(ledger.balance('cust_1'), 1500);
});

test('redelivering the same event does not credit twice', async () => {
  const ledger = newLedger();
  const body = paymentEvent('evt_1', 'cust_1', 500);

  await handlePaymentWebhook(body, ledger);
  const second = await handlePaymentWebhook(body, ledger);

  assert.deepEqual(second, { status: 200, outcome: 'duplicate' });
  assert.equal(ledger.balance('cust_1'), 1500);
});

test('a transient failure returns 500 and the retry credits exactly once', async () => {
  let failuresLeft = 1;
  const ledger = newLedger({
    beforeCommit: () => {
      if (failuresLeft > 0) {
        failuresLeft -= 1;
        throw new TransientError('database timeout');
      }
    },
  });
  const body = paymentEvent('evt_1', 'cust_1', 500);

  const first = await handlePaymentWebhook(body, ledger);
  assert.deepEqual(first, { status: 500, outcome: 'retry' });
  assert.equal(ledger.balance('cust_1'), 1000);
  assert.equal(ledger.hasApplied('evt_1'), false);

  const retry = await handlePaymentWebhook(body, ledger);
  assert.deepEqual(retry, { status: 200, outcome: 'credited' });
  assert.equal(ledger.balance('cust_1'), 1500);
});

test('concurrent deliveries of the same event credit once', async () => {
  const ledger = newLedger();
  const body = paymentEvent('evt_1', 'cust_1', 500);

  const results = await Promise.all([
    handlePaymentWebhook(body, ledger),
    handlePaymentWebhook(body, ledger),
    handlePaymentWebhook(body, ledger),
  ]);

  assert.equal(results.filter((r) => r.outcome === 'credited').length, 1);
  assert.equal(results.filter((r) => r.outcome === 'duplicate').length, 2);
  assert.equal(ledger.balance('cust_1'), 1500);
});

test('an event for an unknown customer returns 422 and credits nothing', async () => {
  const ledger = newLedger();
  const result = await handlePaymentWebhook(paymentEvent('evt_9', 'cust_missing'), ledger);
  assert.deepEqual(result, { status: 422, outcome: 'unknown_customer' });
  assert.equal(ledger.hasApplied('evt_9'), false);
});

test('malformed bodies return 400 and credit nothing', async () => {
  const ledger = newLedger();
  const bodies = [
    'not json',
    JSON.stringify({ type: 'payment.succeeded', data: { customerId: 'cust_1', amountCents: 500 } }),
    JSON.stringify({ id: 'evt_2', type: 'payment.succeeded', data: { customerId: 'cust_1', amountCents: 5.5 } }),
    JSON.stringify({ id: 'evt_3', type: 'payment.succeeded', data: { customerId: 'cust_1', amountCents: -1 } }),
    JSON.stringify({ id: 'evt_4', type: 'payment.succeeded', data: { amountCents: 500 } }),
  ];
  for (const body of bodies) {
    assert.deepEqual(await handlePaymentWebhook(body, ledger), { status: 400, outcome: 'invalid' });
  }
  assert.equal(ledger.balance('cust_1'), 1000);
});

test('other event types are acknowledged and ignored', async () => {
  const ledger = newLedger();
  const body = JSON.stringify({ id: 'evt_5', type: 'payment.refunded', data: {} });
  assert.deepEqual(await handlePaymentWebhook(body, ledger), { status: 200, outcome: 'ignored' });
  assert.equal(ledger.balance('cust_1'), 1000);
});

// Account ledger. Credits are recorded together with the event id that caused
// them, so a provider redelivering the same event never credits twice.

export class TransientError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "TransientError";
  }
}

export type CreditResult = "applied" | "duplicate";

export interface Ledger {
  // Credits `amountCents` to `customerId` exactly once per `eventId`.
  applyCredit(eventId: string, customerId: string, amountCents: number): Promise<CreditResult>;
  balance(customerId: string): Promise<number>;
}

export class InMemoryLedger implements Ledger {
  private readonly balances = new Map<string, number>();
  private readonly appliedEvents = new Set<string>();

  async applyCredit(eventId: string, customerId: string, amountCents: number): Promise<CreditResult> {
    // No await between the check and the write, so this is atomic in-process.
    if (this.appliedEvents.has(eventId)) {
      return "duplicate";
    }
    this.balances.set(customerId, (this.balances.get(customerId) ?? 0) + amountCents);
    this.appliedEvents.add(eventId);
    return "applied";
  }

  async balance(customerId: string): Promise<number> {
    return this.balances.get(customerId) ?? 0;
  }
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { InMemoryLedger } from "../src/ledger.ts";

test("applyCredit adds the amount to the customer balance", async () => {
  const ledger = new InMemoryLedger();
  assert.equal(await ledger.applyCredit("evt_1", "cus_1", 500), "applied");
  assert.equal(await ledger.applyCredit("evt_2", "cus_1", 250), "applied");
  assert.equal(await ledger.balance("cus_1"), 750);
});

test("applyCredit ignores a repeated event id", async () => {
  const ledger = new InMemoryLedger();
  assert.equal(await ledger.applyCredit("evt_1", "cus_1", 500), "applied");
  assert.equal(await ledger.applyCredit("evt_1", "cus_1", 500), "duplicate");
  assert.equal(await ledger.balance("cus_1"), 500);
});

test("balance of an unknown customer is zero", async () => {
  const ledger = new InMemoryLedger();
  assert.equal(await ledger.balance("cus_missing"), 0);
});

import { TransientError } from "./ledger.ts";
import type { Ledger } from "./ledger.ts";

export const PAYMENT_SUCCEEDED = "payment.succeeded";

export type WebhookResponse =
  | { status: 200; outcome: "applied" | "duplicate" | "ignored" }
  | { status: 400; error: string }
  | { status: 503; error: string };

export interface WebhookDeps {
  ledger: Ledger;
  // Attempts made for a single delivery before giving up on a transient error.
  maxAttempts?: number;
  // Base delay between attempts; doubled after each failed attempt.
  retryDelayMs?: number;
  sleep?: (ms: number) => Promise<void>;
}

interface PaymentSucceededEvent {
  id: string;
  customerId: string;
  amountCents: number;
}

type ParseResult = { ok: true; event: PaymentSucceededEvent } | { ok: false; error: string };

const defaultSleep = (ms: number): Promise<void> =>
  new Promise((resolve) => setTimeout(resolve, ms));

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function parsePaymentSucceeded(body: unknown): ParseResult {
  if (!isRecord(body)) {
    return { ok: false, error: "body must be an object" };
  }
  if (typeof body.id !== "string" || body.id === "") {
    return { ok: false, error: "id must be a non-empty string" };
  }
  if (!isRecord(body.data)) {
    return { ok: false, error: "data must be an object" };
  }
  const { customerId, amountCents } = body.data;
  if (typeof customerId !== "string" || customerId === "") {
    return { ok: false, error: "data.customerId must be a non-empty string" };
  }
  if (typeof amountCents !== "number" || !Number.isSafeInteger(amountCents) || amountCents <= 0) {
    return { ok: false, error: "data.amountCents must be a positive integer" };
  }
  return { ok: true, event: { id: body.id, customerId, amountCents } };
}

// Handles one delivery of a payment-provider webhook. The provider retries any
// non-2xx response, so a 503 here means "try again later" and a 400 means
// "this payload will never succeed".
export async function handlePaymentWebhook(body: unknown, deps: WebhookDeps): Promise<WebhookResponse> {
  const maxAttempts = deps.maxAttempts ?? 3;
  const retryDelayMs = deps.retryDelayMs ?? 100;
  const sleep = deps.sleep ?? defaultSleep;

  if (isRecord(body) && body.type !== PAYMENT_SUCCEEDED) {
    return { status: 200, outcome: "ignored" };
  }

  const parsed = parsePaymentSucceeded(body);
  if (!parsed.ok) {
    return { status: 400, error: parsed.error };
  }
  const { id, customerId, amountCents } = parsed.event;

  for (let attempt = 1; ; attempt++) {
    try {
      const outcome = await deps.ledger.applyCredit(id, customerId, amountCents);
      return { status: 200, outcome };
    } catch (err) {
      if (!(err instanceof TransientError)) {
        throw err;
      }
      if (attempt >= maxAttempts) {
        return { status: 503, error: "temporarily unable to process event" };
      }
      await sleep(retryDelayMs * 2 ** (attempt - 1));
    }
  }
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { InMemoryLedger, TransientError } from "../src/ledger.ts";
import type { CreditResult, Ledger } from "../src/ledger.ts";
import { handlePaymentWebhook } from "../src/webhook.ts";

const noSleep = async (): Promise<void> => {};

function paymentEvent(overrides: Record<string, unknown> = {}) {
  return {
    id: "evt_1",
    type: "payment.succeeded",
    data: { customerId: "cus_1", amountCents: 1500 },
    ...overrides,
  };
}

// Wraps a ledger and makes the first `failures` credit attempts throw a
// TransientError, as a database hiccup would.
class FlakyLedger implements Ledger {
  attempts = 0;
  private readonly inner: Ledger;
  private failures: number;

  constructor(inner: Ledger, failures: number) {
    this.inner = inner;
    this.failures = failures;
  }

  async applyCredit(eventId: string, customerId: string, amountCents: number): Promise<CreditResult> {
    this.attempts++;
    if (this.failures > 0) {
      this.failures--;
      throw new TransientError("database unavailable");
    }
    return this.inner.applyCredit(eventId, customerId, amountCents);
  }

  balance(customerId: string): Promise<number> {
    return this.inner.balance(customerId);
  }
}

test("payment.succeeded credits the customer", async () => {
  const ledger = new InMemoryLedger();
  const res = await handlePaymentWebhook(paymentEvent(), { ledger, sleep: noSleep });
  assert.deepEqual(res, { status: 200, outcome: "applied" });
  assert.equal(await ledger.balance("cus_1"), 1500);
});

test("a redelivered event is acknowledged but credited only once", async () => {
  const ledger = new InMemoryLedger();
  const deps = { ledger, sleep: noSleep };
  await handlePaymentWebhook(paymentEvent(), deps);
  const res = await handlePaymentWebhook(paymentEvent(), deps);
  assert.deepEqual(res, { status: 200, outcome: "duplicate" });
  assert.equal(await ledger.balance("cus_1"), 1500);
});

test("other event types are acknowledged and ignored", async () => {
  const ledger = new InMemoryLedger();
  const res = await handlePaymentWebhook(paymentEvent({ type: "payment.failed" }), {
    ledger,
    sleep: noSleep,
  });
  assert.deepEqual(res, { status: 200, outcome: "ignored" });
  assert.equal(await ledger.balance("cus_1"), 0);
});

test("malformed payloads are rejected with 400 and not credited", async () => {
  const bad: unknown[] = [
    null,
    "payment.succeeded",
    paymentEvent({ id: "" }),
    paymentEvent({ data: undefined }),
    paymentEvent({ data: { customerId: "", amountCents: 100 } }),
    paymentEvent({ data: { customerId: "cus_1", amountCents: 0 } }),
    paymentEvent({ data: { customerId: "cus_1", amountCents: -5 } }),
    paymentEvent({ data: { customerId: "cus_1", amountCents: 12.5 } }),
    paymentEvent({ data: { customerId: "cus_1", amountCents: "1500" } }),
  ];
  for (const body of bad) {
    const ledger = new InMemoryLedger();
    const res = await handlePaymentWebhook(body, { ledger, sleep: noSleep });
    assert.equal(res.status, 400, JSON.stringify(body));
    assert.equal(await ledger.balance("cus_1"), 0);
  }
});

test("a transient failure is retried and the credit lands once", async () => {
  const inner = new InMemoryLedger();
  const ledger = new FlakyLedger(inner, 2);
  const res = await handlePaymentWebhook(paymentEvent(), { ledger, maxAttempts: 3, sleep: noSleep });
  assert.deepEqual(res, { status: 200, outcome: "applied" });
  assert.equal(ledger.attempts, 3);
  assert.equal(await inner.balance("cus_1"), 1500);
});

test("backoff doubles between retries", async () => {
  const waits: number[] = [];
  const ledger = new FlakyLedger(new InMemoryLedger(), 3);
  await handlePaymentWebhook(paymentEvent(), {
    ledger,
    maxAttempts: 4,
    retryDelayMs: 50,
    sleep: async (ms) => {
      waits.push(ms);
    },
  });
  assert.deepEqual(waits, [50, 100, 200]);
});

test("persistent transient failure returns 503 and the provider's redelivery credits once", async () => {
  const inner = new InMemoryLedger();
  const ledger = new FlakyLedger(inner, 3);
  const deps = { ledger, maxAttempts: 3, sleep: noSleep };

  const first = await handlePaymentWebhook(paymentEvent(), deps);
  assert.equal(first.status, 503);
  assert.equal(await inner.balance("cus_1"), 0);

  const second = await handlePaymentWebhook(paymentEvent(), deps);
  assert.deepEqual(second, { status: 200, outcome: "applied" });
  assert.equal(await inner.balance("cus_1"), 1500);
});

test("non-transient ledger errors propagate", async () => {
  const broken: Ledger = {
    async applyCredit() {
      throw new Error("schema mismatch");
    },
    async balance() {
      return 0;
    },
  };
  await assert.rejects(
    handlePaymentWebhook(paymentEvent(), { ledger: broken, sleep: noSleep }),
    /schema mismatch/,
  );
});

