export interface FeatureFlags {
  exportCsv: boolean;
  sso: boolean;
  auditLog: boolean;
  betaDashboard: boolean;
}

export interface Limits {
  maxUsers: number;
  maxProjects: number;
  apiRequestsPerMinute: number;
}

export interface OrgDefaults {
  featureFlags: FeatureFlags;
  limits: Limits;
}

const ORG_DEFAULTS: OrgDefaults = {
  featureFlags: {
    exportCsv: false,
    sso: false,
    auditLog: true,
    betaDashboard: false,
  },
  limits: {
    maxUsers: 50,
    maxProjects: 10,
    apiRequestsPerMinute: 600,
  },
};

// Returns a fresh copy so callers cannot mutate the organization defaults.
export function getOrgDefaults(): OrgDefaults {
  return structuredClone(ORG_DEFAULTS);
}

import { getOrgDefaults, type FeatureFlags, type Limits, type OrgDefaults } from "./defaults.ts";

const SECTIONS = ["featureFlags", "limits"] as const;
type Section = (typeof SECTIONS)[number];

// The overrides a tenant has set. Only keys that differ from the org defaults are present.
export interface Overrides {
  featureFlags?: Partial<FeatureFlags>;
  limits?: Partial<Limits>;
}

// A patch merges into the tenant's overrides. A `null` value removes that override,
// so the key falls back to the organization default.
export interface OverridePatch {
  featureFlags?: { [K in keyof FeatureFlags]?: FeatureFlags[K] | null };
  limits?: { [K in keyof Limits]?: Limits[K] | null };
}

export interface EffectiveConfig {
  featureFlags: FeatureFlags;
  limits: Limits;
}

type Bag = Record<string, unknown>;

function assertPlainObject(value: unknown, name: string): asserts value is Bag {
  if (typeof value !== "object" || value === null || Array.isArray(value)) {
    throw new TypeError(`${name} must be an object`);
  }
}

function validateValue(org: OrgDefaults, section: Section, key: string, value: unknown): void {
  const expectedType = typeof (org[section] as Bag)[key];
  const path = `${section}.${key}`;
  if (typeof value !== expectedType) {
    throw new TypeError(`${path} must be a ${expectedType}`);
  }
  if (section === "limits" && (!Number.isInteger(value) || (value as number) < 0)) {
    throw new RangeError(`${path} must be a non-negative integer`);
  }
}

// Validates the whole patch before applying it, so a bad patch changes nothing.
function applyPatch(org: OrgDefaults, current: Overrides, patch: OverridePatch): Overrides {
  assertPlainObject(patch, "patch");
  for (const key of Object.keys(patch)) {
    if (!(SECTIONS as readonly string[]).includes(key)) {
      throw new Error(`Unknown override section: ${key}`);
    }
  }

  const next: Overrides = structuredClone(current);
  for (const section of SECTIONS) {
    const sectionPatch = patch[section];
    if (sectionPatch === undefined) continue;
    assertPlainObject(sectionPatch, section);

    const orgSection = org[section] as Bag;
    const target = ((next[section] ??= {}) as Bag);
    for (const [key, value] of Object.entries(sectionPatch)) {
      if (!Object.hasOwn(orgSection, key)) {
        throw new Error(`Unknown ${section} key: ${key}`);
      }
      if (value === null) {
        delete target[key];
      } else {
        validateValue(org, section, key, value);
        target[key] = value;
      }
    }
    if (Object.keys(target).length === 0) {
      delete next[section];
    }
  }
  return next;
}

export class TenantConfigStore {
  readonly #org: OrgDefaults;
  readonly #overrides = new Map<string, Overrides>();

  constructor(org: OrgDefaults = getOrgDefaults()) {
    this.#org = structuredClone(org);
  }

  // Merges a patch into a tenant's overrides and returns the tenant's resulting overrides.
  updateOverrides(tenantId: string, patch: OverridePatch): Overrides {
    const current = this.#overrides.get(tenantId) ?? {};
    const next = applyPatch(this.#org, current, patch);
    if (Object.keys(next).length === 0) {
      this.#overrides.delete(tenantId);
    } else {
      this.#overrides.set(tenantId, next);
    }
    return structuredClone(next);
  }

  getOverrides(tenantId: string): Overrides {
    return structuredClone(this.#overrides.get(tenantId) ?? {});
  }

  // The configuration a tenant actually gets: organization defaults with the tenant's overrides on top.
  getEffectiveConfig(tenantId: string): EffectiveConfig {
    const overrides = this.#overrides.get(tenantId) ?? {};
    return {
      featureFlags: { ...this.#org.featureFlags, ...overrides.featureFlags },
      limits: { ...this.#org.limits, ...overrides.limits },
    };
  }
}

import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { getOrgDefaults } from "../src/defaults.ts";
import { TenantConfigStore } from "../src/tenant-config.ts";

describe("TenantConfigStore", () => {
  it("gives a tenant without overrides the organization defaults", () => {
    const store = new TenantConfigStore();
    assert.deepEqual(store.getEffectiveConfig("acme"), getOrgDefaults());
    assert.deepEqual(store.getOverrides("acme"), {});
  });

  it("applies a tenant's flag and limit overrides on top of the defaults", () => {
    const store = new TenantConfigStore();
    store.updateOverrides("acme", {
      featureFlags: { sso: true },
      limits: { maxUsers: 500 },
    });

    const config = store.getEffectiveConfig("acme");
    assert.equal(config.featureFlags.sso, true);
    assert.equal(config.featureFlags.exportCsv, false);
    assert.equal(config.limits.maxUsers, 500);
    assert.equal(config.limits.maxProjects, 10);
  });

  it("does not affect other tenants or the organization defaults", () => {
    const store = new TenantConfigStore();
    store.updateOverrides("acme", { limits: { maxProjects: 100 } });

    assert.equal(store.getEffectiveConfig("globex").limits.maxProjects, 10);
    assert.deepEqual(store.getEffectiveConfig("globex"), getOrgDefaults());
  });

  it("merges successive patches instead of replacing earlier overrides", () => {
    const store = new TenantConfigStore();
    store.updateOverrides("acme", { featureFlags: { sso: true } });
    store.updateOverrides("acme", { featureFlags: { betaDashboard: true } });

    assert.deepEqual(store.getOverrides("acme"), {
      featureFlags: { sso: true, betaDashboard: true },
    });
  });

  it("reverts a single override to the organization default when given null", () => {
    const store = new TenantConfigStore();
    store.updateOverrides("acme", { limits: { maxUsers: 500, maxProjects: 20 } });
    store.updateOverrides("acme", { limits: { maxUsers: null } });

    const config = store.getEffectiveConfig("acme");
    assert.equal(config.limits.maxUsers, 50);
    assert.equal(config.limits.maxProjects, 20);
  });

  it("drops the tenant entry once all of its overrides are removed", () => {
    const store = new TenantConfigStore();
    store.updateOverrides("acme", { featureFlags: { sso: true } });
    const result = store.updateOverrides("acme", { featureFlags: { sso: null } });

    assert.deepEqual(result, {});
    assert.deepEqual(store.getOverrides("acme"), {});
    assert.deepEqual(store.getEffectiveConfig("acme"), getOrgDefaults());
  });

  it("returns copies so callers cannot change stored state", () => {
    const store = new TenantConfigStore();
    store.updateOverrides("acme", { limits: { maxUsers: 500 } });

    const config = store.getEffectiveConfig("acme");
    config.limits.maxUsers = 1;
    config.featureFlags.sso = true;
    store.getOverrides("acme").limits!.maxUsers = 1;

    assert.equal(store.getEffectiveConfig("acme").limits.maxUsers, 500);
    assert.equal(store.getEffectiveConfig("acme").featureFlags.sso, false);
  });

  it("does not share state with the organization defaults passed in", () => {
    const org = getOrgDefaults();
    const store = new TenantConfigStore(org);
    org.limits.maxUsers = 1;

    assert.equal(store.getEffectiveConfig("acme").limits.maxUsers, 50);
  });

  it("rejects unknown sections and keys", () => {
    const store = new TenantConfigStore();
    assert.throws(() => store.updateOverrides("acme", { billing: {} } as never), /Unknown override section/);
    assert.throws(() => store.updateOverrides("acme", { featureFlags: { nope: true } } as never), /Unknown featureFlags key: nope/);
    assert.throws(() => store.updateOverrides("acme", { limits: { nope: 1 } } as never), /Unknown limits key: nope/);
  });

  it("rejects values of the wrong type", () => {
    const store = new TenantConfigStore();
    assert.throws(() => store.updateOverrides("acme", { featureFlags: { sso: "yes" } } as never), TypeError);
    assert.throws(() => store.updateOverrides("acme", { limits: { maxUsers: "50" } } as never), TypeError);
  });

  it("rejects limits that are not non-negative integers", () => {
    const store = new TenantConfigStore();
    assert.throws(() => store.updateOverrides("acme", { limits: { maxUsers: -1 } }), RangeError);
    assert.throws(() => store.updateOverrides("acme", { limits: { maxUsers: 1.5 } }), RangeError);
    assert.throws(() => store.updateOverrides("acme", { limits: { maxUsers: Number.NaN } }), RangeError);
    assert.equal(store.updateOverrides("acme", { limits: { maxUsers: 0 } }).limits?.maxUsers, 0);
  });

  it("leaves stored overrides unchanged when a patch is invalid", () => {
    const store = new TenantConfigStore();
    store.updateOverrides("acme", { featureFlags: { sso: true } });

    assert.throws(
      () => store.updateOverrides("acme", { featureFlags: { betaDashboard: true }, limits: { maxUsers: -5 } }),
      RangeError,
    );
    assert.deepEqual(store.getOverrides("acme"), { featureFlags: { sso: true } });
  });
});

// Organization-wide defaults for feature flags and limits. Every tenant starts
// from these values and may override individual entries.
export const ORG_DEFAULTS = {
  featureFlags: {
    betaDashboard: false,
    exportCsv: true,
    ssoLogin: false,
  },
  limits: {
    maxUsers: 100,
    maxProjects: 10,
    apiRequestsPerMinute: 600,
  },
} as const;

export type FeatureFlagName = keyof typeof ORG_DEFAULTS.featureFlags;
export type LimitName = keyof typeof ORG_DEFAULTS.limits;

export type FeatureFlags = Record<FeatureFlagName, boolean>;
export type Limits = Record<LimitName, number>;

// Partial overrides as stored per tenant. Missing keys inherit the org default.
export interface TenantOverrides {
  featureFlags?: Partial<FeatureFlags>;
  limits?: Partial<Limits>;
}

export interface TenantConfig {
  featureFlags: FeatureFlags;
  limits: Limits;
}

const FLAG_NAMES = Object.keys(ORG_DEFAULTS.featureFlags) as FeatureFlagName[];
const LIMIT_NAMES = Object.keys(ORG_DEFAULTS.limits) as LimitName[];

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function assertKnownKeys(
  section: string,
  input: Record<string, unknown>,
  allowed: readonly string[],
): void {
  for (const key of Object.keys(input)) {
    if (!allowed.includes(key)) {
      throw new TypeError(`Unknown ${section} "${key}"`);
    }
  }
}

// Validates untrusted input (e.g. an admin API body) and returns a clean copy.
export function parseTenantOverrides(input: unknown): TenantOverrides {
  if (!isPlainObject(input)) {
    throw new TypeError("Tenant overrides must be an object");
  }
  assertKnownKeys("section", input, ["featureFlags", "limits"]);

  const result: TenantOverrides = {};

  if (input.featureFlags !== undefined) {
    if (!isPlainObject(input.featureFlags)) {
      throw new TypeError("featureFlags must be an object");
    }
    assertKnownKeys("feature flag", input.featureFlags, FLAG_NAMES);
    const flags: Partial<FeatureFlags> = {};
    for (const name of FLAG_NAMES) {
      const value = input.featureFlags[name];
      if (value === undefined) continue;
      if (typeof value !== "boolean") {
        throw new TypeError(`Feature flag "${name}" must be a boolean`);
      }
      flags[name] = value;
    }
    result.featureFlags = flags;
  }

  if (input.limits !== undefined) {
    if (!isPlainObject(input.limits)) {
      throw new TypeError("limits must be an object");
    }
    assertKnownKeys("limit", input.limits, LIMIT_NAMES);
    const limits: Partial<Limits> = {};
    for (const name of LIMIT_NAMES) {
      const value = input.limits[name];
      if (value === undefined) continue;
      if (!Number.isSafeInteger(value) || (value as number) < 0) {
        throw new TypeError(`Limit "${name}" must be a non-negative integer`);
      }
      limits[name] = value as number;
    }
    result.limits = limits;
  }

  return result;
}

// Merges a tenant's overrides over the organization defaults.
export function resolveTenantConfig(
  overrides: TenantOverrides = {},
  defaults: TenantConfig = ORG_DEFAULTS,
): TenantConfig {
  return {
    featureFlags: { ...defaults.featureFlags, ...overrides.featureFlags },
    limits: { ...defaults.limits, ...overrides.limits },
  };
}

import {
  parseTenantOverrides,
  resolveTenantConfig,
  type TenantConfig,
  type TenantOverrides,
} from "./config.ts";

// Holds per-tenant overrides. Tenants without overrides get the org defaults.
export class TenantConfigStore {
  readonly #overrides = new Map<string, TenantOverrides>();

  // Replaces the tenant's overrides. Keys omitted from the input fall back to
  // the organization default. Passing empty overrides resets the tenant.
  setOverrides(tenantId: string, input: unknown): TenantOverrides {
    const parsed = parseTenantOverrides(input);
    if (parsed.featureFlags === undefined && parsed.limits === undefined) {
      this.#overrides.delete(tenantId);
    } else {
      this.#overrides.set(tenantId, parsed);
    }
    return parsed;
  }

  getOverrides(tenantId: string): TenantOverrides {
    return structuredClone(this.#overrides.get(tenantId) ?? {});
  }

  getConfig(tenantId: string): TenantConfig {
    return resolveTenantConfig(this.#overrides.get(tenantId));
  }
}

import { test } from "node:test";
import assert from "node:assert/strict";
import {
  ORG_DEFAULTS,
  parseTenantOverrides,
  resolveTenantConfig,
} from "../src/config.ts";

test("resolveTenantConfig returns org defaults without overrides", () => {
  const config = resolveTenantConfig();
  assert.deepEqual(config.featureFlags, ORG_DEFAULTS.featureFlags);
  assert.deepEqual(config.limits, ORG_DEFAULTS.limits);
});

test("resolveTenantConfig overrides only the given keys", () => {
  const config = resolveTenantConfig({
    featureFlags: { betaDashboard: true },
    limits: { maxUsers: 500 },
  });
  assert.equal(config.featureFlags.betaDashboard, true);
  assert.equal(config.featureFlags.exportCsv, ORG_DEFAULTS.featureFlags.exportCsv);
  assert.equal(config.limits.maxUsers, 500);
  assert.equal(config.limits.maxProjects, ORG_DEFAULTS.limits.maxProjects);
});

test("resolveTenantConfig does not mutate the defaults", () => {
  resolveTenantConfig({ limits: { maxUsers: 1 }, featureFlags: { ssoLogin: true } });
  assert.equal(ORG_DEFAULTS.limits.maxUsers, 100);
  assert.equal(ORG_DEFAULTS.featureFlags.ssoLogin, false);
});

test("parseTenantOverrides accepts valid input", () => {
  assert.deepEqual(
    parseTenantOverrides({ featureFlags: { exportCsv: false }, limits: { maxProjects: 0 } }),
    { featureFlags: { exportCsv: false }, limits: { maxProjects: 0 } },
  );
});

test("parseTenantOverrides rejects non-object input", () => {
  assert.throws(() => parseTenantOverrides(null), TypeError);
  assert.throws(() => parseTenantOverrides([]), TypeError);
  assert.throws(() => parseTenantOverrides("x"), TypeError);
});

test("parseTenantOverrides rejects unknown sections and keys", () => {
  assert.throws(() => parseTenantOverrides({ quotas: {} }), /Unknown section/);
  assert.throws(() => parseTenantOverrides({ featureFlags: { nope: true } }), /Unknown feature flag/);
  assert.throws(() => parseTenantOverrides({ limits: { nope: 1 } }), /Unknown limit/);
});

test("parseTenantOverrides rejects wrong value types", () => {
  assert.throws(() => parseTenantOverrides({ featureFlags: { exportCsv: "yes" } }), /must be a boolean/);
  assert.throws(() => parseTenantOverrides({ limits: { maxUsers: -1 } }), /non-negative integer/);
  assert.throws(() => parseTenantOverrides({ limits: { maxUsers: 1.5 } }), /non-negative integer/);
  assert.throws(() => parseTenantOverrides({ limits: { maxUsers: "10" } }), /non-negative integer/);
  assert.throws(() => parseTenantOverrides({ featureFlags: [] }), /must be an object/);
});

import { test } from "node:test";
import assert from "node:assert/strict";
import { ORG_DEFAULTS } from "../src/config.ts";
import { TenantConfigStore } from "../src/tenant-config-store.ts";

test("unconfigured tenant gets org defaults", () => {
  const store = new TenantConfigStore();
  assert.deepEqual(store.getConfig("acme").limits, ORG_DEFAULTS.limits);
  assert.deepEqual(store.getOverrides("acme"), {});
});

test("tenant overrides do not leak into other tenants", () => {
  const store = new TenantConfigStore();
  store.setOverrides("acme", { featureFlags: { betaDashboard: true }, limits: { maxUsers: 5 } });

  const acme = store.getConfig("acme");
  const globex = store.getConfig("globex");

  assert.equal(acme.featureFlags.betaDashboard, true);
  assert.equal(acme.limits.maxUsers, 5);
  assert.equal(globex.featureFlags.betaDashboard, ORG_DEFAULTS.featureFlags.betaDashboard);
  assert.equal(globex.limits.maxUsers, ORG_DEFAULTS.limits.maxUsers);
});

test("setOverrides replaces previous overrides", () => {
  const store = new TenantConfigStore();
  store.setOverrides("acme", { limits: { maxUsers: 5 } });
  store.setOverrides("acme", { limits: { maxProjects: 2 } });

  const config = store.getConfig("acme");
  assert.equal(config.limits.maxUsers, ORG_DEFAULTS.limits.maxUsers);
  assert.equal(config.limits.maxProjects, 2);
});

test("empty overrides reset the tenant to org defaults", () => {
  const store = new TenantConfigStore();
  store.setOverrides("acme", { featureFlags: { ssoLogin: true } });
  store.setOverrides("acme", {});

  assert.deepEqual(store.getConfig("acme").featureFlags, ORG_DEFAULTS.featureFlags);
  assert.deepEqual(store.getOverrides("acme"), {});
});

test("invalid overrides are rejected and leave stored state unchanged", () => {
  const store = new TenantConfigStore();
  store.setOverrides("acme", { limits: { maxUsers: 5 } });

  assert.throws(() => store.setOverrides("acme", { limits: { maxUsers: -3 } }), TypeError);
  assert.equal(store.getConfig("acme").limits.maxUsers, 5);
});

test("getOverrides returns a copy that cannot modify stored state", () => {
  const store = new TenantConfigStore();
  store.setOverrides("acme", { limits: { maxUsers: 5 } });

  const copy = store.getOverrides("acme");
  copy.limits!.maxUsers = 999;

  assert.equal(store.getConfig("acme").limits.maxUsers, 5);
});

/** A period of unavailability. Times are epoch milliseconds, end is exclusive. */
export interface Outage {
  startMs: number;
  endMs: number;
}

export interface Period {
  startMs: number;
  endMs: number;
}

/** Tolerance used when comparing availability ratios, so exact boundaries are not lost to float error. */
const RATIO_EPSILON = 1e-12;

export function periodDurationMs(period: Period): number {
  const duration = period.endMs - period.startMs;
  if (!(duration > 0)) {
    throw new RangeError(`billing period must end after it starts (start=${period.startMs}, end=${period.endMs})`);
  }
  return duration;
}

/**
 * Total downtime in milliseconds inside the billing period.
 * Outages are clipped to the period and overlapping outages are counted once.
 */
export function measureDowntimeMs(outages: readonly Outage[], period: Period): number {
  periodDurationMs(period); // validates the period

  const clipped: Outage[] = [];
  for (const outage of outages) {
    if (!(outage.endMs >= outage.startMs)) {
      throw new RangeError(`outage ends before it starts (start=${outage.startMs}, end=${outage.endMs})`);
    }
    const startMs = Math.max(outage.startMs, period.startMs);
    const endMs = Math.min(outage.endMs, period.endMs);
    if (endMs > startMs) {
      clipped.push({ startMs, endMs });
    }
  }

  clipped.sort((a, b) => a.startMs - b.startMs);

  let total = 0;
  let current: Outage | undefined;
  for (const outage of clipped) {
    if (current && outage.startMs <= current.endMs) {
      current.endMs = Math.max(current.endMs, outage.endMs);
    } else {
      if (current) total += current.endMs - current.startMs;
      current = { ...outage };
    }
  }
  if (current) total += current.endMs - current.startMs;

  return total;
}

/** Availability as a ratio in [0, 1]: the share of the billing period without downtime. */
export function availabilityRatio(downtimeMs: number, period: Period): number {
  const periodDuration = periodDurationMs(period);
  const ratio = 1 - downtimeMs / periodDuration;
  return Math.min(1, Math.max(0, ratio));
}

/** True when measured availability is strictly below the threshold ratio (e.g. 0.999). */
export function isBelow(availability: number, threshold: number): boolean {
  return availability + RATIO_EPSILON < threshold;
}

import { test } from "node:test";
import assert from "node:assert/strict";
import {
  availabilityRatio,
  isBelow,
  measureDowntimeMs,
  periodDurationMs,
} from "../src/availability.ts";

const MINUTE = 60_000;
const DAY = 24 * 60 * MINUTE;
const period = { startMs: 0, endMs: 30 * DAY };

test("no outages means no downtime and full availability", () => {
  assert.equal(measureDowntimeMs([], period), 0);
  assert.equal(availabilityRatio(0, period), 1);
});

test("sums disjoint outages", () => {
  const outages = [
    { startMs: 1 * DAY, endMs: 1 * DAY + 10 * MINUTE },
    { startMs: 5 * DAY, endMs: 5 * DAY + 5 * MINUTE },
  ];
  assert.equal(measureDowntimeMs(outages, period), 15 * MINUTE);
});

test("overlapping outages are counted once", () => {
  const outages = [
    { startMs: 100, endMs: 300 },
    { startMs: 200, endMs: 400 },
    { startMs: 350, endMs: 360 },
  ];
  assert.equal(measureDowntimeMs(outages, { startMs: 0, endMs: 1000 }), 300);
});

test("outages are clipped to the billing period", () => {
  const outages = [
    { startMs: -5 * MINUTE, endMs: 10 * MINUTE }, // starts before period
    { startMs: 30 * DAY - 5 * MINUTE, endMs: 31 * DAY }, // ends after period
    { startMs: -DAY, endMs: -DAY + MINUTE }, // entirely before period
  ];
  assert.equal(measureDowntimeMs(outages, period), 15 * MINUTE);
});

test("zero-length outages contribute nothing", () => {
  assert.equal(measureDowntimeMs([{ startMs: 500, endMs: 500 }], { startMs: 0, endMs: 1000 }), 0);
});

test("rejects outages that end before they start", () => {
  assert.throws(() => measureDowntimeMs([{ startMs: 10, endMs: 5 }], { startMs: 0, endMs: 100 }), RangeError);
});

test("rejects empty or inverted billing periods", () => {
  assert.throws(() => periodDurationMs({ startMs: 10, endMs: 10 }), RangeError);
  assert.throws(() => measureDowntimeMs([], { startMs: 10, endMs: 5 }), RangeError);
});

test("availability is the share of the period without downtime", () => {
  // 43.2 minutes of downtime in a 30-day month is exactly 99.9% availability.
  const downtime = 43.2 * MINUTE;
  assert.ok(Math.abs(availabilityRatio(downtime, period) - 0.999) < 1e-12);
});

test("availability is clamped to [0, 1]", () => {
  assert.equal(availabilityRatio(40 * DAY, period), 0);
  assert.equal(availabilityRatio(-1, period), 1);
});

test("isBelow treats exact threshold as meeting the SLA", () => {
  const exactlyTarget = availabilityRatio(43.2 * MINUTE, period);
  assert.equal(isBelow(exactlyTarget, 0.999), false);
  assert.equal(isBelow(0.9989, 0.999), true);
  assert.equal(isBelow(0.9991, 0.999), false);
});

import type { SlaCreditResult } from "./sla.ts";

export interface InvoiceLine {
  description: string;
  /** Amount in integer minor units (cents). Credits are negative. */
  amountCents: number;
}

export interface Invoice {
  currency: string;
  lines: readonly InvoiceLine[];
}

export function invoiceTotalCents(invoice: Invoice): number {
  return invoice.lines.reduce((sum, line) => sum + line.amountCents, 0);
}

/**
 * Returns a new invoice with an SLA credit line appended. The input is not
 * mutated. When no credit is owed, the invoice is returned unchanged.
 */
export function applySlaCredit(invoice: Invoice, credit: SlaCreditResult): Invoice {
  if (credit.creditCents <= 0) {
    return invoice;
  }
  const percent = (credit.availability * 100).toFixed(2);
  return {
    currency: invoice.currency,
    lines: [
      ...invoice.lines,
      {
        description: `SLA credit (availability ${percent}%, ${Math.round(credit.creditRate * 100)}% of monthly fee)`,
        amountCents: -credit.creditCents,
      },
    ],
  };
}

import {
  availabilityRatio,
  isBelow,
  measureDowntimeMs,
  type Outage,
  type Period,
} from "./availability.ts";

export interface CreditTier {
  /** Applies when measured availability is strictly below this ratio (e.g. 0.99). */
  belowAvailability: number;
  /** Share of the monthly fee credited, as a ratio in (0, 1]. */
  creditRate: number;
}

export interface SlaPolicy {
  /** Availability the SLA promises, as a ratio (e.g. 0.999 for 99.9%). */
  targetAvailability: number;
  /** Credit tiers. The deepest matching tier (highest credit rate) wins. */
  creditTiers: readonly CreditTier[];
}

export interface SlaCreditInput {
  outages: readonly Outage[];
  period: Period;
  /** Monthly fee the credit is calculated on, in integer minor units (cents). */
  monthlyFeeCents: number;
  policy?: SlaPolicy;
}

export interface SlaCreditResult {
  downtimeMs: number;
  availability: number;
  breached: boolean;
  creditRate: number;
  creditCents: number;
}

export const DEFAULT_SLA_POLICY: SlaPolicy = {
  targetAvailability: 0.999,
  creditTiers: [
    { belowAvailability: 0.999, creditRate: 0.1 },
    { belowAvailability: 0.99, creditRate: 0.25 },
    { belowAvailability: 0.95, creditRate: 0.5 },
  ],
};

/** Credit rate for a measured availability: the largest rate among tiers it falls below, or 0. */
export function creditRateFor(availability: number, policy: SlaPolicy): number {
  let rate = 0;
  for (const tier of policy.creditTiers) {
    if (isBelow(availability, tier.belowAvailability) && tier.creditRate > rate) {
      rate = tier.creditRate;
    }
  }
  return rate;
}

/**
 * Measures outages against the SLA for one billing period and computes the
 * credit owed. The credit is rounded to the nearest cent.
 */
export function computeSlaCredit(input: SlaCreditInput): SlaCreditResult {
  const policy = input.policy ?? DEFAULT_SLA_POLICY;
  if (!Number.isInteger(input.monthlyFeeCents) || input.monthlyFeeCents < 0) {
    throw new RangeError(`monthlyFeeCents must be a non-negative integer, got ${input.monthlyFeeCents}`);
  }

  const downtimeMs = measureDowntimeMs(input.outages, input.period);
  const availability = availabilityRatio(downtimeMs, input.period);
  const breached = isBelow(availability, policy.targetAvailability);
  const creditRate = breached ? creditRateFor(availability, policy) : 0;
  const creditCents = Math.round(input.monthlyFeeCents * creditRate);

  return { downtimeMs, availability, breached, creditRate, creditCents };
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { computeSlaCredit, creditRateFor, DEFAULT_SLA_POLICY } from "../src/sla.ts";
import { applySlaCredit, invoiceTotalCents, type Invoice } from "../src/invoice.ts";

const MINUTE = 60_000;
const DAY = 24 * 60 * MINUTE;
const period = { startMs: 0, endMs: 30 * DAY }; // 30-day billing month
const FEE = 10_000; // 100.00 in cents

function outageOf(minutes: number) {
  return [{ startMs: 1 * DAY, endMs: 1 * DAY + minutes * MINUTE }];
}

test("no breach when downtime is exactly at the 99.9% allowance", () => {
  const result = computeSlaCredit({ outages: outageOf(43.2), period, monthlyFeeCents: FEE });
  assert.equal(result.breached, false);
  assert.equal(result.creditCents, 0);
});

test("breach just above the allowance earns the first tier", () => {
  const result = computeSlaCredit({ outages: outageOf(44), period, monthlyFeeCents: FEE });
  assert.equal(result.breached, true);
  assert.equal(result.creditRate, 0.1);
  assert.equal(result.creditCents, 1_000);
});

test("deeper outages earn deeper tiers", () => {
  // ~99.5% availability -> 10% tier
  assert.equal(computeSlaCredit({ outages: outageOf(216), period, monthlyFeeCents: FEE }).creditRate, 0.1);
  // ~98.5% availability -> 25% tier
  assert.equal(computeSlaCredit({ outages: outageOf(648), period, monthlyFeeCents: FEE }).creditRate, 0.25);
  // ~90% availability -> 50% tier
  assert.equal(computeSlaCredit({ outages: outageOf(4320), period, monthlyFeeCents: FEE }).creditRate, 0.5);
});

test("credit is capped at the top tier even for total outages", () => {
  const result = computeSlaCredit({
    outages: [{ startMs: 0, endMs: 60 * DAY }],
    period,
    monthlyFeeCents: FEE,
  });
  assert.equal(result.availability, 0);
  assert.equal(result.creditCents, 5_000);
});

test("overlapping outages are not double counted in the credit", () => {
  const outages = [
    { startMs: 1 * DAY, endMs: 1 * DAY + 30 * MINUTE },
    { startMs: 1 * DAY + 20 * MINUTE, endMs: 1 * DAY + 40 * MINUTE },
  ];
  const result = computeSlaCredit({ outages, period, monthlyFeeCents: FEE });
  assert.equal(result.downtimeMs, 40 * MINUTE);
});

test("rounds the credit to the nearest cent", () => {
  const result = computeSlaCredit({ outages: outageOf(44), period, monthlyFeeCents: 1_005 });
  assert.equal(result.creditCents, 101); // 100.5 cents rounds to 101
});

test("custom policy overrides the default", () => {
  const policy = { targetAvailability: 0.99, creditTiers: [{ belowAvailability: 0.99, creditRate: 0.3 }] };
  const result = computeSlaCredit({ outages: outageOf(44), period, monthlyFeeCents: FEE, policy });
  assert.equal(result.breached, false);
  assert.equal(result.creditCents, 0);
});

test("creditRateFor returns 0 with no matching tier", () => {
  assert.equal(creditRateFor(0.9999, DEFAULT_SLA_POLICY), 0);
});

test("rejects a non-integer or negative fee", () => {
  assert.throws(() => computeSlaCredit({ outages: [], period, monthlyFeeCents: 10.5 }), RangeError);
  assert.throws(() => computeSlaCredit({ outages: [], period, monthlyFeeCents: -1 }), RangeError);
});

test("applySlaCredit adds a negative line and reduces the total", () => {
  const invoice: Invoice = {
    currency: "EUR",
    lines: [{ description: "Monthly subscription", amountCents: FEE }],
  };
  const credit = computeSlaCredit({ outages: outageOf(4320), period, monthlyFeeCents: FEE });
  const billed = applySlaCredit(invoice, credit);

  assert.equal(billed.lines.length, 2);
  assert.equal(billed.lines[1].amountCents, -5_000);
  assert.match(billed.lines[1].description, /SLA credit/);
  assert.equal(invoiceTotalCents(billed), 5_000);
  // input is not mutated
  assert.equal(invoice.lines.length, 1);
});

test("applySlaCredit returns the invoice unchanged when no credit is owed", () => {
  const invoice: Invoice = { currency: "EUR", lines: [{ description: "Fee", amountCents: FEE }] };
  const credit = computeSlaCredit({ outages: [], period, monthlyFeeCents: FEE });
  assert.equal(applySlaCredit(invoice, credit), invoice);
});

