export const SECOND_MS = 1_000;
export const MINUTE_MS = 60 * SECOND_MS;
export const HOUR_MS = 60 * MINUTE_MS;
export const DAY_MS = 24 * HOUR_MS;

export function minutes(count: number): number {
  return count * MINUTE_MS;
}

export function hours(count: number): number {
  return count * HOUR_MS;
}

export function days(count: number): number {
  return count * DAY_MS;
}

export interface Outage {
  startMs: number;
  endMs: number;
}

/**
 * Total milliseconds of outage inside [windowStartMs, windowEndMs).
 * Outages are clipped to the window and overlapping outages are merged,
 * so an interval covered twice is counted once.
 */
export function downtimeWithin(
  outages: readonly Outage[],
  windowStartMs: number,
  windowEndMs: number,
): number {
  if (windowEndMs < windowStartMs) {
    throw new RangeError("window ends before it starts");
  }

  const clipped: Outage[] = [];
  for (const outage of outages) {
    if (outage.endMs < outage.startMs) {
      throw new RangeError("outage ends before it starts");
    }
    const startMs = Math.max(outage.startMs, windowStartMs);
    const endMs = Math.min(outage.endMs, windowEndMs);
    if (endMs > startMs) {
      clipped.push({ startMs, endMs });
    }
  }
  clipped.sort((a, b) => a.startMs - b.startMs);

  let total = 0;
  let runStart: number | undefined;
  let runEnd = 0;
  for (const outage of clipped) {
    if (runStart === undefined || outage.startMs > runEnd) {
      if (runStart !== undefined) {
        total += runEnd - runStart;
      }
      runStart = outage.startMs;
      runEnd = outage.endMs;
    } else {
      runEnd = Math.max(runEnd, outage.endMs);
    }
  }
  if (runStart !== undefined) {
    total += runEnd - runStart;
  }
  return total;
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { DAY_MS, HOUR_MS, MINUTE_MS, days, hours, minutes } from "../src/duration.ts";

test("duration helpers return milliseconds", () => {
  assert.equal(MINUTE_MS, 60_000);
  assert.equal(minutes(5), 300_000);
  assert.equal(hours(2), 2 * HOUR_MS);
  assert.equal(days(1), DAY_MS);
});

import { test } from "node:test";
import assert from "node:assert/strict";
import { downtimeWithin } from "../src/outages.ts";

const WINDOW_START = 1_000;
const WINDOW_END = 11_000;

test("sums outages inside the window", () => {
  const outages = [
    { startMs: 2_000, endMs: 3_000 },
    { startMs: 5_000, endMs: 6_500 },
  ];
  assert.equal(downtimeWithin(outages, WINDOW_START, WINDOW_END), 2_500);
});

test("clips outages that cross the window edges", () => {
  const outages = [
    { startMs: 0, endMs: 2_000 },
    { startMs: 10_000, endMs: 20_000 },
  ];
  assert.equal(downtimeWithin(outages, WINDOW_START, WINDOW_END), 2_000);
});

test("ignores outages entirely outside the window", () => {
  const outages = [{ startMs: 0, endMs: 500 }, { startMs: 12_000, endMs: 13_000 }];
  assert.equal(downtimeWithin(outages, WINDOW_START, WINDOW_END), 0);
});

test("merges overlapping outages so shared time is counted once", () => {
  const outages = [
    { startMs: 2_000, endMs: 5_000 },
    { startMs: 4_000, endMs: 6_000 },
    { startMs: 2_500, endMs: 3_000 },
  ];
  assert.equal(downtimeWithin(outages, WINDOW_START, WINDOW_END), 4_000);
});

test("returns zero when there are no outages", () => {
  assert.equal(downtimeWithin([], WINDOW_START, WINDOW_END), 0);
});

test("rejects an outage that ends before it starts", () => {
  assert.throws(() => downtimeWithin([{ startMs: 5, endMs: 4 }], 0, 10), RangeError);
});

test("rejects a window that ends before it starts", () => {
  assert.throws(() => downtimeWithin([], 10, 0), RangeError);
});

import { downtimeWithin, type Outage } from "./outages.ts";

export interface SlaPolicy {
  /** Availability target as a fraction, e.g. 0.999 for 99.9%. */
  uptimeTarget: number;
  /** Percent of the period's fee credited when the target is missed (0-100). */
  creditPercent: number;
}

export interface BillingPeriod {
  startMs: number;
  endMs: number;
}

export interface SlaEvaluation {
  periodMs: number;
  allowedDowntimeMs: number;
  downtimeMs: number;
  breached: boolean;
  creditCents: number;
}

/** Downtime a period may contain while still meeting the uptime target. */
export function allowedDowntime(periodMs: number, uptimeTarget: number): number {
  // Rounded to the nearest millisecond so float error cannot shift the threshold.
  return Math.round(periodMs * (1 - uptimeTarget));
}

export function evaluateSla(options: {
  policy: SlaPolicy;
  period: BillingPeriod;
  outages: readonly Outage[];
  monthlyFeeCents: number;
}): SlaEvaluation {
  const { policy, period, outages, monthlyFeeCents } = options;

  if (!(policy.uptimeTarget > 0 && policy.uptimeTarget < 1)) {
    throw new RangeError("uptimeTarget must be between 0 and 1 exclusive");
  }
  if (!(policy.creditPercent >= 0 && policy.creditPercent <= 100)) {
    throw new RangeError("creditPercent must be between 0 and 100");
  }
  if (!Number.isInteger(monthlyFeeCents) || monthlyFeeCents < 0) {
    throw new RangeError("monthlyFeeCents must be a non-negative integer");
  }

  const periodMs = period.endMs - period.startMs;
  const allowedMs = allowedDowntime(periodMs, policy.uptimeTarget);
  const downtimeMs = downtimeWithin(outages, period.startMs, period.endMs);
  const breached = downtimeMs > allowedMs;

  return {
    periodMs,
    allowedDowntimeMs: allowedMs,
    downtimeMs,
    breached,
    creditCents: breached ? Math.floor((monthlyFeeCents * policy.creditPercent) / 100) : 0,
  };
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { DAY_MS, minutes } from "../src/duration.ts";
import { allowedDowntime, evaluateSla } from "../src/sla.ts";

const period = { startMs: 0, endMs: 30 * DAY_MS };
const policy = { uptimeTarget: 0.999, creditPercent: 10 };

test("allowed downtime is the complement of the uptime target", () => {
  // 30 days at 99.9% allows 43.2 minutes.
  assert.equal(allowedDowntime(30 * DAY_MS, 0.999), minutes(43.2));
});

test("no credit when downtime is exactly at the threshold", () => {
  const allowed = allowedDowntime(period.endMs - period.startMs, policy.uptimeTarget);
  const result = evaluateSla({
    policy,
    period,
    outages: [{ startMs: 0, endMs: allowed }],
    monthlyFeeCents: 10_000,
  });
  assert.equal(result.breached, false);
  assert.equal(result.creditCents, 0);
});

test("credits the configured percent of the fee when downtime exceeds the threshold", () => {
  const result = evaluateSla({
    policy,
    period,
    outages: [{ startMs: 0, endMs: minutes(60) }],
    monthlyFeeCents: 10_000,
  });
  assert.equal(result.breached, true);
  assert.equal(result.downtimeMs, minutes(60));
  assert.equal(result.allowedDowntimeMs, minutes(43.2));
  assert.equal(result.creditCents, 1_000);
});

test("credit is rounded down to whole cents", () => {
  const result = evaluateSla({
    policy: { uptimeTarget: 0.999, creditPercent: 33 },
    period,
    outages: [{ startMs: 0, endMs: minutes(60) }],
    monthlyFeeCents: 1_000,
  });
  assert.equal(result.creditCents, 330);
});

test("outages outside the billing period do not count", () => {
  const result = evaluateSla({
    policy,
    period,
    outages: [{ startMs: -minutes(600), endMs: -minutes(1) }],
    monthlyFeeCents: 10_000,
  });
  assert.equal(result.downtimeMs, 0);
  assert.equal(result.breached, false);
});

test("rejects invalid policies and fees", () => {
  const outages: never[] = [];
  assert.throws(
    () => evaluateSla({ policy: { uptimeTarget: 1, creditPercent: 10 }, period, outages, monthlyFeeCents: 1 }),
    RangeError,
  );
  assert.throws(
    () => evaluateSla({ policy: { uptimeTarget: 0.99, creditPercent: 101 }, period, outages, monthlyFeeCents: 1 }),
    RangeError,
  );
  assert.throws(
    () => evaluateSla({ policy, period, outages, monthlyFeeCents: 10.5 }),
    RangeError,
  );
});

