export interface InvoiceLine {
  description: string;
  /** Negative for credits. */
  amountCents: number;
}

export interface Invoice {
  id: string;
  lines: readonly InvoiceLine[];
  totalCents: number;
}

export const SLA_CREDIT_DESCRIPTION = "SLA credit";

/**
 * Returns a new invoice with an SLA credit line appended and the total reduced.
 * The credit is capped at the invoice total so the total never goes negative.
 * Passing a zero credit returns the invoice unchanged.
 */
export function applySlaCredit(invoice: Invoice, creditCents: number): Invoice {
  if (!Number.isInteger(creditCents) || creditCents < 0) {
    throw new RangeError("creditCents must be a non-negative integer");
  }
  const applied = Math.min(creditCents, Math.max(0, invoice.totalCents));
  if (applied === 0) {
    return invoice;
  }
  return {
    ...invoice,
    lines: [...invoice.lines, { description: SLA_CREDIT_DESCRIPTION, amountCents: -applied }],
    totalCents: invoice.totalCents - applied,
  };
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { applySlaCredit, type Invoice } from "../src/invoice.ts";

const invoice: Invoice = {
  id: "INV-1",
  lines: [{ description: "Subscription", amountCents: 10_000 }],
  totalCents: 10_000,
};

test("appends a negative SLA credit line and reduces the total", () => {
  const result = applySlaCredit(invoice, 1_000);
  assert.deepEqual(result.lines, [
    { description: "Subscription", amountCents: 10_000 },
    { description: "SLA credit", amountCents: -1_000 },
  ]);
  assert.equal(result.totalCents, 9_000);
  assert.equal(result.id, "INV-1");
});

test("does not modify the original invoice", () => {
  applySlaCredit(invoice, 1_000);
  assert.equal(invoice.lines.length, 1);
  assert.equal(invoice.totalCents, 10_000);
});

test("a zero credit leaves the invoice unchanged", () => {
  assert.equal(applySlaCredit(invoice, 0), invoice);
});

test("caps the credit at the invoice total", () => {
  const result = applySlaCredit({ ...invoice, totalCents: 500 }, 1_000);
  assert.equal(result.totalCents, 0);
  assert.equal(result.lines.at(-1)?.amountCents, -500);
});

test("rejects a negative or fractional credit", () => {
  assert.throws(() => applySlaCredit(invoice, -1), RangeError);
  assert.throws(() => applySlaCredit(invoice, 1.5), RangeError);
});

