export interface RateLimiterOptions {
  /** Maximum number of requests a single client may make within one window. */
  limit: number;
  /** Window length in milliseconds. Defaults to one minute. */
  windowMs?: number;
}

export interface RateLimitDecision {
  allowed: boolean;
  /** Requests the client may still make in the current window. */
  remaining: number;
  /** When rejected, milliseconds until the client may retry. Zero when allowed. */
  retryAfterMs: number;
}

const ONE_MINUTE_MS = 60_000;

/**
 * Per-client sliding-window rate limiter.
 *
 * Each client gets at most `limit` requests in any `windowMs` span. The caller
 * supplies `now` (milliseconds) on every call; the limiter never reads the clock.
 */
export class RateLimiter {
  readonly #limit: number;
  readonly #windowMs: number;
  readonly #hits = new Map<string, number[]>();

  constructor(options: RateLimiterOptions) {
    const windowMs = options.windowMs ?? ONE_MINUTE_MS;
    if (!Number.isInteger(options.limit) || options.limit < 1) {
      throw new RangeError(`limit must be a positive integer, got ${options.limit}`);
    }
    if (!Number.isFinite(windowMs) || windowMs <= 0) {
      throw new RangeError(`windowMs must be a positive number, got ${windowMs}`);
    }
    this.#limit = options.limit;
    this.#windowMs = windowMs;
  }

  /** Records a request from `clientId` at time `now` if it is within the limit. */
  check(clientId: string, now: number): RateLimitDecision {
    const cutoff = now - this.#windowMs;
    const hits = (this.#hits.get(clientId) ?? []).filter((t) => t > cutoff);

    if (hits.length >= this.#limit) {
      this.#hits.set(clientId, hits);
      // The oldest hit in the window is the first to expire, freeing a slot.
      const retryAfterMs = hits[0] + this.#windowMs - now;
      return { allowed: false, remaining: 0, retryAfterMs };
    }

    hits.push(now);
    this.#hits.set(clientId, hits);
    return { allowed: true, remaining: this.#limit - hits.length, retryAfterMs: 0 };
  }
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { RateLimiter } from "../src/rate-limiter.ts";

test("allows requests up to the limit within a window", () => {
  const limiter = new RateLimiter({ limit: 3 });
  assert.deepEqual(limiter.check("a", 0), { allowed: true, remaining: 2, retryAfterMs: 0 });
  assert.deepEqual(limiter.check("a", 1), { allowed: true, remaining: 1, retryAfterMs: 0 });
  assert.deepEqual(limiter.check("a", 2), { allowed: true, remaining: 0, retryAfterMs: 0 });
});

test("rejects the request after the limit is reached, with retry time", () => {
  const limiter = new RateLimiter({ limit: 2, windowMs: 60_000 });
  limiter.check("a", 1_000);
  limiter.check("a", 5_000);
  assert.deepEqual(limiter.check("a", 10_000), {
    allowed: false,
    remaining: 0,
    retryAfterMs: 1_000 + 60_000 - 10_000,
  });
});

test("rejected requests are not counted against the client", () => {
  const limiter = new RateLimiter({ limit: 1, windowMs: 1_000 });
  assert.equal(limiter.check("a", 0).allowed, true);
  assert.equal(limiter.check("a", 100).allowed, false);
  assert.equal(limiter.check("a", 200).allowed, false);
  // Only the first request at t=0 counts, so a request at t=1000 is allowed.
  assert.equal(limiter.check("a", 1_000).allowed, true);
});

test("slots free up as old requests leave the window", () => {
  const limiter = new RateLimiter({ limit: 2, windowMs: 60_000 });
  limiter.check("a", 0);
  limiter.check("a", 30_000);
  assert.equal(limiter.check("a", 59_999).allowed, false);
  assert.equal(limiter.check("a", 60_000).allowed, true); // t=0 has aged out
  assert.equal(limiter.check("a", 60_001).allowed, false); // t=30000 still counts
  assert.equal(limiter.check("a", 90_000).allowed, true);
});

test("each client has its own budget", () => {
  const limiter = new RateLimiter({ limit: 1 });
  assert.equal(limiter.check("alice", 0).allowed, true);
  assert.equal(limiter.check("alice", 1).allowed, false);
  assert.equal(limiter.check("bob", 1).allowed, true);
});

test("defaults the window to one minute", () => {
  const limiter = new RateLimiter({ limit: 1 });
  limiter.check("a", 0);
  assert.equal(limiter.check("a", 59_999).allowed, false);
  assert.equal(limiter.check("a", 60_000).allowed, true);
});

test("rejects invalid options", () => {
  assert.throws(() => new RateLimiter({ limit: 0 }), RangeError);
  assert.throws(() => new RateLimiter({ limit: 1.5 }), RangeError);
  assert.throws(() => new RateLimiter({ limit: 1, windowMs: 0 }), RangeError);
});

export interface RateLimiterOptions {
  /** Maximum number of requests a client may make within one window. */
  limit: number;
  /** Window length in milliseconds. Defaults to one minute. */
  windowMs?: number;
}

export interface RateLimitDecision {
  allowed: boolean;
  /** Requests the client may still make in the current window. */
  remaining: number;
  /** Milliseconds until the client may retry; 0 when allowed. */
  retryAfterMs: number;
}

/**
 * Per-client sliding-window rate limiter.
 *
 * Keeps the timestamps of each client's accepted requests within the last
 * `windowMs` milliseconds. A request is allowed while fewer than `limit`
 * timestamps remain in the window. Callers pass `now`; the limiter never
 * reads the clock itself.
 */
export class RateLimiter {
  readonly limit: number;
  readonly windowMs: number;
  private readonly hits = new Map<string, number[]>();

  constructor(options: RateLimiterOptions) {
    const windowMs = options.windowMs ?? 60_000;
    if (!Number.isInteger(options.limit) || options.limit < 1) {
      throw new RangeError(`limit must be a positive integer, got ${options.limit}`);
    }
    if (!(windowMs > 0)) {
      throw new RangeError(`windowMs must be positive, got ${windowMs}`);
    }
    this.limit = options.limit;
    this.windowMs = windowMs;
  }

  /** Records a request from `clientId` at time `now` and reports whether it is allowed. */
  check(clientId: string, now: number): RateLimitDecision {
    const windowStart = now - this.windowMs;
    const recent = (this.hits.get(clientId) ?? []).filter((t) => t > windowStart);

    if (recent.length >= this.limit) {
      this.hits.set(clientId, recent);
      return {
        allowed: false,
        remaining: 0,
        retryAfterMs: recent[0] + this.windowMs - now,
      };
    }

    recent.push(now);
    this.hits.set(clientId, recent);
    return {
      allowed: true,
      remaining: this.limit - recent.length,
      retryAfterMs: 0,
    };
  }
}

import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { RateLimiter } from "../src/limiter.ts";

describe("RateLimiter", () => {
  it("allows up to the limit within one window and rejects the next request", () => {
    const limiter = new RateLimiter({ limit: 3 });
    assert.equal(limiter.check("a", 0).allowed, true);
    assert.equal(limiter.check("a", 1).allowed, true);
    assert.equal(limiter.check("a", 2).allowed, true);
    const denied = limiter.check("a", 3);
    assert.equal(denied.allowed, false);
    assert.equal(denied.remaining, 0);
  });

  it("reports remaining requests after each accepted call", () => {
    const limiter = new RateLimiter({ limit: 3 });
    assert.equal(limiter.check("a", 0).remaining, 2);
    assert.equal(limiter.check("a", 1).remaining, 1);
    assert.equal(limiter.check("a", 2).remaining, 0);
  });

  it("tracks clients independently", () => {
    const limiter = new RateLimiter({ limit: 1 });
    assert.equal(limiter.check("a", 0).allowed, true);
    assert.equal(limiter.check("a", 1).allowed, false);
    assert.equal(limiter.check("b", 1).allowed, true);
  });

  it("does not count rejected requests against the client", () => {
    const limiter = new RateLimiter({ limit: 1, windowMs: 1000 });
    assert.equal(limiter.check("a", 0).allowed, true);
    assert.equal(limiter.check("a", 500).allowed, false);
    assert.equal(limiter.check("a", 999).allowed, false);
    // Only the request at t=0 is in the window; it expires at t=1000.
    assert.equal(limiter.check("a", 1000).allowed, true);
  });

  it("frees capacity as old requests leave the sliding window", () => {
    const limiter = new RateLimiter({ limit: 2, windowMs: 1000 });
    assert.equal(limiter.check("a", 0).allowed, true);
    assert.equal(limiter.check("a", 400).allowed, true);
    assert.equal(limiter.check("a", 500).allowed, false);
    // At t=1000 the request from t=0 has aged out, but the one from t=400 has not.
    const decision = limiter.check("a", 1000);
    assert.equal(decision.allowed, true);
    assert.equal(decision.remaining, 0);
    assert.equal(limiter.check("a", 1100).allowed, false);
  });

  it("reports how long until the oldest request leaves the window", () => {
    const limiter = new RateLimiter({ limit: 2, windowMs: 60_000 });
    limiter.check("a", 10_000);
    limiter.check("a", 20_000);
    const denied = limiter.check("a", 25_000);
    assert.equal(denied.allowed, false);
    assert.equal(denied.retryAfterMs, 10_000 + 60_000 - 25_000);
  });

  it("returns zero retryAfterMs when allowed", () => {
    const limiter = new RateLimiter({ limit: 1 });
    assert.equal(limiter.check("a", 0).retryAfterMs, 0);
  });

  it("defaults the window to one minute", () => {
    const limiter = new RateLimiter({ limit: 1 });
    assert.equal(limiter.windowMs, 60_000);
    limiter.check("a", 0);
    assert.equal(limiter.check("a", 59_999).allowed, false);
    assert.equal(limiter.check("a", 60_000).allowed, true);
  });

  it("rejects a limit that is not a positive integer", () => {
    assert.throws(() => new RateLimiter({ limit: 0 }), RangeError);
    assert.throws(() => new RateLimiter({ limit: -1 }), RangeError);
    assert.throws(() => new RateLimiter({ limit: 1.5 }), RangeError);
  });

  it("rejects a non-positive window", () => {
    assert.throws(() => new RateLimiter({ limit: 1, windowMs: 0 }), RangeError);
    assert.throws(() => new RateLimiter({ limit: 1, windowMs: -5 }), RangeError);
  });
});

export interface LineItem {
  sku: string;
  unitPriceCents: number;
  quantity: number;
}

export interface OrderTotals {
  subtotalCents: number;
  discountCents: number;
  totalCents: number;
}

export function lineTotalCents(item: LineItem): number {
  if (!Number.isInteger(item.unitPriceCents) || item.unitPriceCents < 0) {
    throw new RangeError(`invalid unit price for ${item.sku}: ${item.unitPriceCents}`);
  }
  if (!Number.isInteger(item.quantity) || item.quantity < 1) {
    throw new RangeError(`invalid quantity for ${item.sku}: ${item.quantity}`);
  }
  return item.unitPriceCents * item.quantity;
}

export function subtotalCents(items: readonly LineItem[]): number {
  return items.reduce((sum, item) => sum + lineTotalCents(item), 0);
}

/**
 * Totals for an order before any discount is applied.
 * Discounts are added by the caller (see `priceOrder` in coupons.ts).
 */
export function orderTotals(items: readonly LineItem[], discountCents = 0): OrderTotals {
  const subtotal = subtotalCents(items);
  const discount = Math.min(Math.max(discountCents, 0), subtotal);
  return {
    subtotalCents: subtotal,
    discountCents: discount,
    totalCents: subtotal - discount,
  };
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { lineTotalCents, orderTotals, subtotalCents } from "../src/pricing.ts";

test("line total multiplies unit price by quantity", () => {
  assert.equal(lineTotalCents({ sku: "a", unitPriceCents: 250, quantity: 3 }), 750);
});

test("subtotal sums all lines", () => {
  const items = [
    { sku: "a", unitPriceCents: 250, quantity: 2 },
    { sku: "b", unitPriceCents: 1999, quantity: 1 },
  ];
  assert.equal(subtotalCents(items), 2499);
});

test("order without discount has total equal to subtotal", () => {
  const totals = orderTotals([{ sku: "a", unitPriceCents: 1000, quantity: 1 }]);
  assert.deepEqual(totals, { subtotalCents: 1000, discountCents: 0, totalCents: 1000 });
});

test("discount is subtracted from the total", () => {
  const totals = orderTotals([{ sku: "a", unitPriceCents: 1000, quantity: 1 }], 150);
  assert.deepEqual(totals, { subtotalCents: 1000, discountCents: 150, totalCents: 850 });
});

test("discount is capped at the subtotal", () => {
  const totals = orderTotals([{ sku: "a", unitPriceCents: 500, quantity: 1 }], 9999);
  assert.deepEqual(totals, { subtotalCents: 500, discountCents: 500, totalCents: 0 });
});

test("rejects non-integer or negative prices", () => {
  assert.throws(() => lineTotalCents({ sku: "a", unitPriceCents: 1.5, quantity: 1 }), RangeError);
  assert.throws(() => lineTotalCents({ sku: "a", unitPriceCents: -1, quantity: 1 }), RangeError);
});

test("rejects quantities below one", () => {
  assert.throws(() => lineTotalCents({ sku: "a", unitPriceCents: 100, quantity: 0 }), RangeError);
});

import { orderTotals, type LineItem, type OrderTotals } from "./pricing.ts";

export type Coupon =
  | { code: string; kind: "percent"; percent: number; expiresAt?: Date }
  | { code: string; kind: "fixed"; amountCents: number; expiresAt?: Date };

export type CouponReason = "expired" | "invalid";

export class CouponError extends Error {
  readonly reason: CouponReason;

  constructor(reason: CouponReason, message: string) {
    super(message);
    this.name = "CouponError";
    this.reason = reason;
  }
}

/** Throws a CouponError if the coupon cannot be used at `now`. */
export function validateCoupon(coupon: Coupon, now: Date = new Date()): void {
  if (coupon.kind === "percent") {
    if (!(coupon.percent > 0 && coupon.percent <= 100)) {
      throw new CouponError("invalid", `coupon ${coupon.code}: percent must be in (0, 100]`);
    }
  } else if (!Number.isInteger(coupon.amountCents) || coupon.amountCents <= 0) {
    throw new CouponError("invalid", `coupon ${coupon.code}: amount must be a positive integer of cents`);
  }
  if (coupon.expiresAt && now.getTime() >= coupon.expiresAt.getTime()) {
    throw new CouponError("expired", `coupon ${coupon.code} expired at ${coupon.expiresAt.toISOString()}`);
  }
}

/**
 * Discount in cents for a coupon against a given subtotal.
 * Percentage discounts are rounded half-up to the nearest cent.
 */
export function discountCents(coupon: Coupon, subtotalCents: number): number {
  if (coupon.kind === "percent") {
    return Math.round((subtotalCents * coupon.percent) / 100);
  }
  return coupon.amountCents;
}

export interface PricedOrder extends OrderTotals {
  couponCode?: string;
}

/**
 * Prices an order, applying the coupon if one is given.
 * Throws CouponError when the coupon is expired or malformed.
 */
export function priceOrder(
  items: readonly LineItem[],
  coupon?: Coupon,
  now: Date = new Date(),
): PricedOrder {
  if (!coupon) {
    return orderTotals(items);
  }
  validateCoupon(coupon, now);
  const subtotal = orderTotals(items).subtotalCents;
  const totals = orderTotals(items, discountCents(coupon, subtotal));
  return { ...totals, couponCode: coupon.code };
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { CouponError, discountCents, priceOrder, validateCoupon, type Coupon } from "../src/coupons.ts";
import type { LineItem } from "../src/pricing.ts";

const cart: LineItem[] = [
  { sku: "shirt", unitPriceCents: 2000, quantity: 2 },
  { sku: "socks", unitPriceCents: 500, quantity: 1 },
];
const now = new Date("2026-10-18T12:00:00Z");

test("percent coupon takes the stated share of the subtotal", () => {
  const coupon: Coupon = { code: "TEN", kind: "percent", percent: 10 };
  const order = priceOrder(cart, coupon, now);
  assert.deepEqual(order, {
    subtotalCents: 4500,
    discountCents: 450,
    totalCents: 4050,
    couponCode: "TEN",
  });
});

test("percent discount rounds half-up to the nearest cent", () => {
  const coupon: Coupon = { code: "HALF", kind: "percent", percent: 50 };
  assert.equal(discountCents(coupon, 1005), 503);
  assert.equal(discountCents(coupon, 1004), 502);
});

test("fixed coupon subtracts its amount", () => {
  const coupon: Coupon = { code: "FIVE", kind: "fixed", amountCents: 500 };
  const order = priceOrder(cart, coupon, now);
  assert.equal(order.totalCents, 4000);
  assert.equal(order.discountCents, 500);
});

test("fixed coupon larger than the order cannot make the total negative", () => {
  const coupon: Coupon = { code: "BIG", kind: "fixed", amountCents: 100000 };
  const order = priceOrder(cart, coupon, now);
  assert.equal(order.discountCents, 4500);
  assert.equal(order.totalCents, 0);
});

test("no coupon leaves the price unchanged", () => {
  const order = priceOrder(cart, undefined, now);
  assert.deepEqual(order, { subtotalCents: 4500, discountCents: 0, totalCents: 4500 });
});

test("expired coupon is rejected", () => {
  const coupon: Coupon = {
    code: "OLD",
    kind: "percent",
    percent: 10,
    expiresAt: new Date("2026-10-01T00:00:00Z"),
  };
  assert.throws(() => priceOrder(cart, coupon, now), (err: unknown) =>
    err instanceof CouponError && err.reason === "expired",
  );
});

test("coupon is still valid before its expiry", () => {
  const coupon: Coupon = {
    code: "SOON",
    kind: "percent",
    percent: 10,
    expiresAt: new Date("2026-12-31T00:00:00Z"),
  };
  assert.equal(priceOrder(cart, coupon, now).totalCents, 4050);
});

test("percent outside (0, 100] is rejected", () => {
  for (const percent of [0, -5, 101, Number.NaN]) {
    assert.throws(
      () => validateCoupon({ code: "BAD", kind: "percent", percent }, now),
      (err: unknown) => err instanceof CouponError && err.reason === "invalid",
    );
  }
});

test("fixed amount must be a positive integer of cents", () => {
  for (const amountCents of [0, -100, 1.5]) {
    assert.throws(
      () => validateCoupon({ code: "BAD", kind: "fixed", amountCents }, now),
      (err: unknown) => err instanceof CouponError && err.reason === "invalid",
    );
  }
});

