// Coupons reduce an order subtotal. Money is integer cents and
// percentages are plain numbers (10 means 10%), per the repo conventions.

export type Coupon =
  | { code: string; kind: "percent"; percent: number }
  | { code: string; kind: "fixed"; amountCents: number };

export interface OrderPricing {
  subtotalCents: number;
  discountCents: number;
  totalCents: number;
}

export function createCoupon(input: Coupon): Coupon {
  const code = normalizeCode(input.code);
  if (code === "") {
    throw new Error("Coupon code must not be empty");
  }
  if (input.kind === "percent") {
    if (!(input.percent > 0 && input.percent <= 100)) {
      throw new Error("Percent coupon must be greater than 0 and at most 100");
    }
    return { code, kind: "percent", percent: input.percent };
  }
  if (input.kind === "fixed") {
    if (!Number.isInteger(input.amountCents) || input.amountCents <= 0) {
      throw new Error("Fixed coupon amount must be a positive integer number of cents");
    }
    return { code, kind: "fixed", amountCents: input.amountCents };
  }
  throw new Error("Unknown coupon kind");
}

export function normalizeCode(code: string): string {
  return code.trim().toUpperCase();
}

// Discount in cents for a subtotal. Percentage discounts are rounded to the
// nearest cent. The discount never exceeds the subtotal.
export function discountFor(coupon: Coupon, subtotalCents: number): number {
  if (!Number.isInteger(subtotalCents) || subtotalCents < 0) {
    throw new Error("Subtotal must be a non-negative integer number of cents");
  }
  const raw =
    coupon.kind === "percent"
      ? Math.round((subtotalCents * coupon.percent) / 100)
      : coupon.amountCents;
  return Math.min(raw, subtotalCents);
}

export function applyCoupon(subtotalCents: number, coupon: Coupon): OrderPricing {
  const discountCents = discountFor(coupon, subtotalCents);
  return {
    subtotalCents,
    discountCents,
    totalCents: subtotalCents - discountCents,
  };
}

// Looks up a customer-entered code in a catalog. Matching ignores case and
// surrounding whitespace.
export function findCoupon(catalog: readonly Coupon[], enteredCode: string): Coupon {
  const code = normalizeCode(enteredCode);
  const coupon = catalog.find((c) => normalizeCode(c.code) === code);
  if (!coupon) {
    throw new Error(`Unknown coupon code: ${code}`);
  }
  return coupon;
}

import { test, describe } from "node:test";
import assert from "node:assert/strict";
import {
  applyCoupon,
  createCoupon,
  discountFor,
  findCoupon,
  type Coupon,
} from "../src/coupons.ts";

describe("applyCoupon", () => {
  test("percent coupon takes the given share of the subtotal", () => {
    const coupon = createCoupon({ code: "SAVE10", kind: "percent", percent: 10 });
    assert.deepEqual(applyCoupon(5000, coupon), {
      subtotalCents: 5000,
      discountCents: 500,
      totalCents: 4500,
    });
  });

  test("percent discount rounds to the nearest cent", () => {
    const coupon = createCoupon({ code: "THIRD", kind: "percent", percent: 33 });
    // 999 * 0.33 = 329.67 -> 330
    assert.equal(discountFor(coupon, 999), 330);
    assert.equal(applyCoupon(999, coupon).totalCents, 669);
  });

  test("fixed coupon subtracts its amount", () => {
    const coupon = createCoupon({ code: "FIVE", kind: "fixed", amountCents: 500 });
    assert.deepEqual(applyCoupon(1234, coupon), {
      subtotalCents: 1234,
      discountCents: 500,
      totalCents: 734,
    });
  });

  test("discount never exceeds the subtotal", () => {
    const coupon = createCoupon({ code: "BIG", kind: "fixed", amountCents: 10000 });
    assert.deepEqual(applyCoupon(2500, coupon), {
      subtotalCents: 2500,
      discountCents: 2500,
      totalCents: 0,
    });
  });

  test("100 percent coupon makes the order free", () => {
    const coupon = createCoupon({ code: "FREE", kind: "percent", percent: 100 });
    assert.equal(applyCoupon(4200, coupon).totalCents, 0);
  });

  test("empty order stays at zero", () => {
    const coupon: Coupon = { code: "SAVE10", kind: "percent", percent: 10 };
    assert.deepEqual(applyCoupon(0, coupon), {
      subtotalCents: 0,
      discountCents: 0,
      totalCents: 0,
    });
  });

  test("rejects a non-integer or negative subtotal", () => {
    const coupon = createCoupon({ code: "SAVE10", kind: "percent", percent: 10 });
    assert.throws(() => applyCoupon(10.5, coupon), /integer number of cents/);
    assert.throws(() => applyCoupon(-1, coupon), /integer number of cents/);
  });
});

describe("createCoupon", () => {
  test("normalizes the code to trimmed upper case", () => {
    assert.equal(
      createCoupon({ code: "  spring ", kind: "percent", percent: 5 }).code,
      "SPRING",
    );
  });

  test("rejects an empty code", () => {
    assert.throws(
      () => createCoupon({ code: "   ", kind: "percent", percent: 5 }),
      /must not be empty/,
    );
  });

  test("rejects percentages outside (0, 100]", () => {
    assert.throws(() => createCoupon({ code: "A", kind: "percent", percent: 0 }));
    assert.throws(() => createCoupon({ code: "A", kind: "percent", percent: -5 }));
    assert.throws(() => createCoupon({ code: "A", kind: "percent", percent: 101 }));
    assert.throws(() => createCoupon({ code: "A", kind: "percent", percent: NaN }));
  });

  test("rejects fixed amounts that are not positive integer cents", () => {
    assert.throws(() => createCoupon({ code: "A", kind: "fixed", amountCents: 0 }));
    assert.throws(() => createCoupon({ code: "A", kind: "fixed", amountCents: -100 }));
    assert.throws(() => createCoupon({ code: "A", kind: "fixed", amountCents: 1.5 }));
  });
});

describe("findCoupon", () => {
  const catalog: Coupon[] = [
    { code: "SAVE10", kind: "percent", percent: 10 },
    { code: "FIVE", kind: "fixed", amountCents: 500 },
  ];

  test("finds a coupon ignoring case and surrounding whitespace", () => {
    assert.equal(findCoupon(catalog, " save10 ").code, "SAVE10");
  });

  test("throws for an unknown code", () => {
    assert.throws(() => findCoupon(catalog, "NOPE"), /Unknown coupon code: NOPE/);
  });
});
